\label{def:main-prompt-generating-process}
Each prompt and its target are generated as follows.
\begin{enumerate}[labelindent=0pt,leftmargin=*,itemsep=2pt,parsep=1pt,topsep=0pt,partopsep=0pt]
  \item Sample a latent task $\Theta\sim\Pi$.

  \item Conditional on $\Theta$, generate $n+1$ complete examples independently from the task-specific distribution:
  \begin{itemize}
    \item For \textbf{sample-only prompts}, a task $\theta$ specifies a distribution $P_\theta$ on ${\mathcal{Z}}$, where $\theta\mapsto P_\theta$ is a Borel probability kernel, and $Z_1,\ldots,Z_n,Z_\star \stackrel{\mathrm{iid}}{\sim}P_\Theta$.
    \item For \textbf{input--output prompts}, fix an input dimension $d_x\ge1$ and let ${\mathcal{X}}=[0,1]^{d_x}$.
    A task $\theta$ specifies a joint distribution $P_\theta^{X,Z}$ on ${\mathcal{X}}\times{\mathcal{Z}}$, where $\theta\mapsto P_\theta^{X,Z}$ is a Borel probability kernel, and $(X_1,Z_1),\ldots,(X_n,Z_n),(X_\star,Z_\star) \stackrel{\mathrm{iid}}{\sim}P_\Theta^{X,Z}$.
  \end{itemize}

  \item Form the context from the first $n$ examples and hold out the output in the final example as the target: $C_n=Z_{1:n}, H_n=C_n$ for sample-only prompts and $C_n=((X_i,Z_i))_{i=1}^n, H_n=(C_n,X_\star)$ for input--output prompts.
\end{enumerate}

\label{thm:main-generation-error}
Under \cref{assump:smooth-latent-task}, for each $n\ge2$ and sufficiently small $\varepsilon>0$, there exists a common DiT class and a choice of diffusion parameters with model size and forward-pass cost polynomial in $(n,\varepsilon^{-1})$. For every fixed $\mathcal{M}\in\mathfrak{M}_{\mathrm{lat}}$ and $\delta\in(0,1)$, pretraining on $N$ independent episodes to empirical optimization gap $\varepsilon_{\mathrm{opt}}\lesssim\varepsilon^2$ and sampling with $M$ admissible reverse steps, as in Section~\ref{subsec:main-training-and-sampling}, yield, with probability at least $1-\delta$ over the training episodes and their diffusion augmentations,
\begin{equation}
{\mathbb{E}}{\mathsf{TV}}\!\bigl(\widehat P^{(M)}_{0\mid H_n},P(\cdot\mid H_n)\bigr)
\lesssim
\varepsilon
+ \log(e/\varepsilon)\sqrt{\frac{\mathsf{N}_{\mathrm{param},n,\varepsilon}^{\mathrm{lat}}\log(en/\varepsilon)+\log(2/\delta)}{N}}
+ \frac{\log(e/\varepsilon)}{\sqrt M},
\label{eq:main-predictive-generation-bound}
\end{equation}
where $\mathsf{N}_{\mathrm{param},n,\varepsilon}^{\mathrm{lat}}$ is the number of trainable parameters.

\label{thm:informal-task-uncertainty}
Under \cref{assump:smooth-latent-task}, the following statements hold.
\begin{itemize}
  \item \textbf{Uniform upper bound.}
  Every $\mathcal{M}\in\mathfrak{M}_{\mathrm{lat}}$ and every $n\ge2$ satisfy
  \begin{equation*}
    {\mathbb{E}}_{\mathcal{M}}\operatorname{TV}\!\left(P(\cdot\mid H_n),P(\cdot\mid H_n,\Theta)\right)
    \lesssim \sqrt{\log n/n}.
  \end{equation*}
  \item \textbf{Matching worst-case lower bound.}
  If, in addition, $H_\theta>0$, $\underline{p}<1$, and $L_\beta>1$, then for every sufficiently large $n$, there is a model $\mathcal{M}_n\in\mathfrak{M}_{\mathrm{lat}}$ for which
  \begin{equation*}
    \inf_{Q^{\mathcal{M}_n}}{\mathbb{E}}_{\mathcal{M}_n}\operatorname{TV}\!\left(Q^{\mathcal{M}_n}(\cdot\mid H_n),P(\cdot\mid H_n,\Theta)\right)
    \gtrsim \sqrt{\log n/n},
  \end{equation*}
  where the infimum is over prompt-only Borel probability kernels from ${\mathcal{H}}_n$ to ${\mathcal{Z}}$ that may know $\mathcal{M}_n$.
\end{itemize}

\label{cor:informal-task-generation}
For sufficiently large $n$, set $\varepsilon=\sqrt{\log n/n}$, use the score class and estimator of \cref{thm:main-generation-error} with $\varepsilon_{\mathrm{opt}}\lesssim\log n/n$, and let $N$ and $M$ satisfy \cref{eq:main-predictive-sufficient-choices} at this value of $\varepsilon$. For every fixed $\mathcal{M}\in\mathfrak{M}_{\mathrm{lat}}$ and $\delta\in(0,1)$, with probability at least $1-\delta$ over pretraining and its diffusion augmentations,
\begin{equation}
  {\mathbb{E}}\operatorname{TV}\!\left(\widehat P^{(M)}_{0\mid H_n},P(\cdot\mid H_n,\Theta)\right)
  \lesssim \sqrt{\frac{\log n}{n}}.
  \label{eq:informal-task-generation}
\end{equation}
Here the expectation is over a fresh test episode conditional on the completed training run.

\label{prop:balanced-dsm-identity}
Define $\widetilde{s}^{\star}(z,t\,|\, h):=\sigma_t s^{\star}(z,t\,|\, h)$.
Then
\begin{equation*}
  {\mathbb{E}}[-\xi_{\mathrm{dsm}} \,|\,
  Z_{\tau}, \tau, H_n]
  = \widetilde{s}^{\star}(Z_{\tau},
  \tau\,|\, H_n)
\end{equation*}
almost surely, and every jointly Borel score $s$ satisfying ${\mathcal{R}}_{\mathrm{bDSM}}(s)<\infty$ obeys
\begin{equation}
  {\mathcal{R}}_{\mathrm{bDSM}}(s)-{\mathcal{R}}_{\mathrm{bDSM}}(s^{\star})
  = {\mathcal{E}}_{\mathrm{score}}(s).
  \label{eq:balanced-dsm-excess-identity}
\end{equation}

\label{lem:balanced-score-truncation}
For the cube-supported posterior-predictive distributions in \cref{app:subsec:probability-conventions}, $\|\widetilde{s}^{\star}(z,t\mid h)\|_2\le R_{\mathrm{bal},n}$ on $\mathcal{G}_n$, and
\begin{equation}
  \delta_{\mathrm{tail},n}
  \le \Pr\!\left(\|\xi\|_2>R_{\mathrm{state},n}-\sqrt{d_z}\right)<1,
  \qquad \xi\sim{\mathcal{N}}(0,I_{d_z}).
  \label{eq:transformer-good-event-probability}
\end{equation}
The squared-score contribution outside the truncation region is finite and satisfies
\begin{align}
  \varepsilon_{\mathrm{tail},n}^2
  &:=A_{t_0,T}{\mathbb{E}}\!\left[
  \|\widetilde{s}^{\star}(Z_{\tau},\tau\mid H_n)\|_2^2
  \operatorname{\mathds{1}}\{(H_n,Z_{\tau},\tau)\notin\mathcal{G}_n\}
  \right]
  \label{eq:transformer-exceptional-score-energy}\\
  &\le \frac{A_{t_0,T}}{\sigma_{t_0}^2}
  {\mathbb{E}}\!\left[
  (\|\xi\|_2+2\sqrt{d_z})^2
  \operatorname{\mathds{1}}\{\|\xi\|_2>R_{\mathrm{state},n}-\sqrt{d_z}\}
  \right].
  \label{eq:derived-score-tail-bound}
\end{align}

\label{lem:positive-smooth-latent-derived-regularity}
Under \cref{assump:smooth-latent-task}, the preceding maps are jointly Borel, and $q_{\theta}(\cdot\,|\, x)$ is a probability density for every $(\theta,x)$.
There are fixed constants $B_{\ell,\mathrm{ctx}}\ge1$, $B_{\ell,\mathrm{qry}}\ge0$, $0<\underline{q}_{\mathrm{out}}\le\overline{q}_{\mathrm{out}}$, and finite H\"older constants such that, for every $\theta,\theta'\in{\mathcal{T}}$, every $c,c'\in[0,1]^{d_{\mathrm{stat}}}$, every $x,x'\in{\mathcal{X}}_{\star}$, and every $z_0\in[0,1]^{d_z}$,
\begin{equation}
  |\ell_{\theta}(c)|\le B_{\ell,\mathrm{ctx}},
  \qquad
  |\ell_{\theta}^{\mathrm{qry}}(x)|\le B_{\ell,\mathrm{qry}},
  \qquad
  \underline{q}_{\mathrm{out}}\le q_{\theta}(z_0\,|\, x)\le\overline{q}_{\mathrm{out}},
  \label{eq:smooth-latent-derived-envelope}
\end{equation}
and
\begin{align}
  |\ell_{\theta}(c)-\ell_{\theta'}(c')|
  &\le
  H_{\ell,\theta}\|\theta-\theta'\|_2^{\beta_{\theta}}
  {}+
  H_{\ell,c}\|c-c'\|_2^{\beta'},
  \label{eq:smooth-latent-context-regularity}\\
  |\ell_{\theta}^{\mathrm{qry}}(x)
  -\ell_{\theta'}^{\mathrm{qry}}(x')|
  &\le
  H_{\mathrm{qry},\theta}\|\theta-\theta'\|_2^{\beta_{\theta}}
  {}+
  H_{\mathrm{qry},x}\|x-x'\|_2^{\beta'},
  \label{eq:smooth-latent-query-regularity}\\
  \sup_{z_0\in[0,1]^{d_z}}
  |q_{\theta}(z_0\,|\, x)-q_{\theta'}(z_0\,|\, x')|
  &\le
  H_{q,\theta}\|\theta-\theta'\|_2^{\beta_{\theta}}
  {}+
  H_{q,x}\|x-x'\|_2^{\beta'}.
  \label{eq:smooth-latent-output-regularity}
\end{align}
In the sample-only prompt model,
\begin{equation*}
  (B_{\ell,\mathrm{qry}},H_{\mathrm{qry},\theta},
  H_{\mathrm{qry},x},H_{q,x})=(0,0,0,0).
\end{equation*}
The constants depend only on the parameters in \cref{assump:smooth-latent-task}; explicit choices for the sample-only and input--output prompt models are given in \cref{eq:positive-smooth-latent-derived-constants,eq:positive-smooth-latent-derived-constants-sample}.

The defining H\"older bound for $\beta\le1$, and the mean-value theorem with the H\"older norm's gradient bound for $\beta>1$, give a constant
\begin{equation*}
  H_{\mathrm{dens}}:=C_{\beta,d_{\mathrm{stat}}}L_{\beta}
\end{equation*}
such that every $g_{\theta}$ in \cref{assump:smooth-latent-task} satisfies
\begin{equation*}
  |g_{\theta}(u)-g_{\theta}(u')|
  \le H_{\mathrm{dens}}\|u-u'\|_2^{\beta'}.
\end{equation*}
Put
\begin{equation*}
  B_{\log}:=1\vee|\log\underline{p}|\vee\log L_{\beta},
  \qquad
  K_q:=\underline{p}^{-1}+L_{\beta}\underline{p}^{-2}.
\end{equation*}
In the input--output prompt model, one may choose
\begin{align}
  B_{\ell,\mathrm{ctx}}=B_{\ell,\mathrm{qry}}&:=B_{\log},
  &
  (\underline{q}_{\mathrm{out}},\overline{q}_{\mathrm{out}})
  &:=\left(\frac{\underline{p}}{L_{\beta}},
  \frac{L_{\beta}}{\underline{p}}\right),
  \nonumber\\
  H_{\ell,\theta}=H_{\mathrm{qry},\theta}
  &:=\frac{H_{\theta}}{\underline{p}},
  &
  H_{\ell,c}=H_{\mathrm{qry},x}
  &:=\frac{H_{\mathrm{dens}}}{\underline{p}},
  \nonumber\\
  H_{q,\theta}&:=K_qH_{\theta},
  &
  H_{q,x}&:=K_qH_{\mathrm{dens}}.
  \label{eq:positive-smooth-latent-derived-constants}
\end{align}
In the sample-only prompt model, one may instead choose
\begin{equation}
  \begin{gathered}
  B_{\ell,\mathrm{ctx}}:=B_{\log},
  \qquad
  (\underline{q}_{\mathrm{out}},\overline{q}_{\mathrm{out}}):=(\underline{p},L_{\beta}),
  \qquad
  H_{\ell,\theta}:=H_{\theta}/\underline{p},
  \qquad
  H_{\ell,c}:=H_{\mathrm{dens}}/\underline{p},
  \\
  H_{q,\theta}:=H_{\theta},
  \qquad
  (B_{\ell,\mathrm{qry}},H_{\mathrm{qry},\theta},
  H_{\mathrm{qry},x},H_{q,x}):=(0,0,0,0).
  \end{gathered}
  \label{eq:positive-smooth-latent-derived-constants-sample}
\end{equation}

We verify the input--output case.
Because the output cube has unit volume,
\begin{equation*}
  \underline{p}\le\lambda_{\theta}(x)\le L_{\beta}
\end{equation*}
and
\begin{equation*}
  |\lambda_{\theta}(x)-\lambda_{\theta'}(x')|
  \le
  H_{\theta}\|\theta-\theta'\|_2^{\beta_{\theta}}
  +H_{\mathrm{dens}}\|x-x'\|_2^{\beta'}.
\end{equation*}
The mean-value theorem for the logarithm on $[\underline{p},L_{\beta}]$ proves the asserted bounds for $\ell_{\theta}$ and $\ell_{\theta}^{\mathrm{qry}}$.
The bounds on $g_{\theta}$ and $\lambda_{\theta}$ give the displayed values of $\underline{q}_{\mathrm{out}}$ and $\overline{q}_{\mathrm{out}}$.
Moreover, for $u=(x,z_0)$ and $u'=(x',z_0)$,
\begin{align*}
  |q_{\theta}(z_0\mid x)-q_{\theta'}(z_0\mid x')|
  &\le
  \frac{|g_{\theta}(u)-g_{\theta'}(u')|}{\underline{p}}
  +\frac{L_{\beta}
  |\lambda_{\theta}(x)-\lambda_{\theta'}(x')|}{\underline{p}^2}
  \\
  &\le
  K_q\left\{
  H_{\theta}\|\theta-\theta'\|_2^{\beta_{\theta}}
  +H_{\mathrm{dens}}\|x-x'\|_2^{\beta'}
  \right\}.
\end{align*}
This proves \cref{eq:smooth-latent-derived-envelope,eq:smooth-latent-context-regularity,eq:smooth-latent-query-regularity,eq:smooth-latent-output-regularity} with \cref{eq:positive-smooth-latent-derived-constants}.
The sample-only case follows directly from $q_{\theta}=g_{\theta}$, the density bounds, the latent modulus, and the mean-value bound for the logarithm, giving \cref{eq:positive-smooth-latent-derived-constants-sample}.
Joint Borel measurability follows from parameterized integration and composition with continuous functions on intervals bounded away from zero.

\label{lem:smooth-latent-normalized-basis-regularity}
Under \cref{assump:smooth-latent-task}, put $\mathcal{U}_{\mathrm{feat}}:=[-1,1]^{d_{\mathrm{stat}}+1}$
and $R_{\mathrm{geom},n}:=1+R_{\mathrm{state},n}+\sqrt{d_z}$.
For every $\theta\in{\mathcal{T}}$, there exist continuous maps
\begin{equation*}
  \overline{\mathsf{a}}_{\theta,n}:\mathcal{U}_{\mathrm{feat}}
  \to[\underline{q}_{\mathrm{out}},\overline{q}_{\mathrm{out}}],
  \qquad
  \overline{\mathsf{b}}_{\theta,n}:\mathcal{U}_{\mathrm{feat}}
  \to\overline{\operatorname{Ball}}(0,R_{\mathrm{num},n}^{\mathrm{lat}}),
\end{equation*}
such that, for every $(h,z,t)\in\mathcal{G}_n$,
\begin{equation*}
  \overline{\mathsf{a}}_{\theta,n}(\mathsf{u}_n(z,t,h))
  =\mathsf{a}_{\theta}(x_{\star},z,t),
  \qquad
  \overline{\mathsf{b}}_{\theta,n}(\mathsf{u}_n(z,t,h))
  =\mathsf{b}_{\theta}(x_{\star},z,t).
\end{equation*}
Moreover, there is a single finite constant $H_{\mathrm{bas},n}$, independent of $\theta$, such that, for all $u,u'\in\mathcal{U}_{\mathrm{feat}}$,
\begin{equation*}
  |\overline{\mathsf{a}}_{\theta,n}(u)-\overline{\mathsf{a}}_{\theta,n}(u')|
  +\|\overline{\mathsf{b}}_{\theta,n}(u)-\overline{\mathsf{b}}_{\theta,n}(u')\|_2
  \le H_{\mathrm{bas},n}\|u-u'\|_2^{\beta'}.
\end{equation*}
The common H\"older constant satisfies
\begin{equation}
  \begin{aligned}
  H_{\mathrm{bas},n}\le{} C_{\mathrm{bas}}\big[&
  1+(1+R_{\mathrm{bal},n})H_{q,x}
  \\
  &+R_{\mathrm{state},n}
  \{R_{\mathrm{geom},n}\sigma_{t_0}^{-2}
  +\sigma_{t_0}^{-1}
  +R_{\mathrm{geom},n}^2\sigma_{t_0}^{-3}\}
  \\
  &+T\{R_{\mathrm{geom},n}^2\sigma_{t_0}^{-4}
  +\sigma_{t_0}^{-1}
  +R_{\mathrm{geom},n}\sigma_{t_0}^{-3}
  +R_{\mathrm{geom},n}^3\sigma_{t_0}^{-5}\}
  \big].
  \end{aligned}
  \label{eq:smooth-latent-basis-regularity}
\end{equation}
Here $0<C_{\mathrm{bas}}<\infty$ depends only on the fixed dimensions, $\beta'$, and the common density bounds.

The Gaussian identities
\begin{align*}
  \nabla_z\Lambda_t(z,y)
  &=-\sigma_t^{-1}I_{d_z},\\
  \nabla_z\log G_t(z,y)
  &=\sigma_t^{-1}\Lambda_t(z,y),\\
  \partial_t\Lambda_t(z,y)
  &=-\frac{\alpha_ty}{\sigma_t}
  -\frac{\alpha_t^2}{\sigma_t^2}\Lambda_t(z,y)
  ,\\
  \partial_t\log G_t(z,y)
  &=-\frac{d_z\alpha_t^2}{\sigma_t^2}
  -\frac{(z-\alpha_ty)^{\top}\alpha_ty}{\sigma_t^2}
  +\frac{\alpha_t^2\|z-\alpha_ty\|_2^2}{\sigma_t^4}
\end{align*}
and the covariance identity below imply the derivative bounds
\begin{align*}
  \|\nabla_z\mathsf{a}_{\theta}\|_2
  &\lesssim R_{\mathrm{geom},n}\sigma_{t_0}^{-2},
  &
  \|\nabla_z\mathsf{b}_{\theta}\|_{\mathrm{op}}
  &\lesssim \sigma_{t_0}^{-1}+R_{\mathrm{geom},n}^2\sigma_{t_0}^{-3},
  \\
  |\partial_t\mathsf{a}_{\theta}|
  &\lesssim R_{\mathrm{geom},n}^2\sigma_{t_0}^{-4},
  &
  \|\partial_t\mathsf{b}_{\theta}\|_2
  &\lesssim \sigma_{t_0}^{-1}+R_{\mathrm{geom},n}\sigma_{t_0}^{-3}
  +R_{\mathrm{geom},n}^3\sigma_{t_0}^{-5}.
\end{align*}
The implicit constants depend only on the fixed dimensions and density bounds.
The denominator $I_t(z)$ causes no extra small-denominator factor because, for every bounded differentiable scalar- or vector-valued integrand $F$ and each coordinate derivative
\begin{equation*}
  D\in\{\partial_t,\partial_{z_1},\ldots,\partial_{z_{d_z}}\},
\end{equation*}
one has, componentwise in the vector-valued case,
\begin{equation}
  D{\mathbb{E}}_{\nu_{z,t}}[F(z,t,Y)]
  ={\mathbb{E}}_{\nu_{z,t}}[D F(z,t,Y)]
  +\operatorname{Cov}_{\nu_{z,t}}
  \bigl(F(z,t,Y),D\log G_t(z,Y)\bigr).
  \label{eq:appendix-smooth-latent-covariance-identity}
\end{equation}
Differentiation is justified by domination on the compact domain for $(x,z,t)$ defined above.
For the query coordinate, \cref{eq:smooth-latent-output-regularity} and \cref{eq:appendix-smooth-latent-normalized-bases} give a $\beta'$-H\"older modulus at most
\begin{equation*}
  (1+R_{\mathrm{bal},n})H_{q,x}.
\end{equation*}
To define the functions approximated by the network on the entire normalized cube, let $u\in\mathcal{U}_{\mathrm{feat}}$, written as $u=(u_x,u_z,u_t)$ in the input--output prompt model and $u=(u_z,u_t)$ in the sample-only prompt model, and set
\begin{equation*}
  \begin{aligned}
  x(u)&:=\begin{cases}
  0,&\text{sample-only},\\
  (u_x+\mathbf{1}_{d_x})/2,&\text{input--output},
  \end{cases}\\
  z(u)&:=R_{\mathrm{state},n}{\mathrm{clip}}_1(u_z),
  &
  t(u)&:=t_0+\frac{T-t_0}{2}(u_t+1).
  \end{aligned}
\end{equation*}
Define the extensions by
\begin{equation*}
  \overline{\mathsf{a}}_{\theta,n}(u)
  :=\mathsf{a}_{\theta}(x(u),z(u),t(u)),
  \qquad
  \overline{\mathsf{b}}_{\theta,n}(u)
  :=\mathsf{b}_{\theta}(x(u),z(u),t(u)).
\end{equation*}
Since ${\mathrm{clip}}_1$ is one-Lipschitz, the three coordinate maps above have Lipschitz constants bounded by a fixed constant, $R_{\mathrm{state},n}$, and $T$, respectively.
Multiplying the state and time derivative bounds by the Lipschitz constants of these coordinate maps and adding the query modulus gives the asserted H\"older inequality, with $H_{\mathrm{bas},n}$ satisfying \cref{eq:smooth-latent-basis-regularity}, after increasing $C_{\mathrm{bas}}$ by a fixed dimension-dependent factor.
By construction, the extensions take values in the ranges stated in the lemma.
For every $(h,z,t)\in\mathcal{G}_n$, the state block of $\mathsf{u}_n(z,t,h)$ lies in the unit ball and represents the unclipped state; substituting the feature coordinates into the definitions above therefore gives $\overline{\mathsf{a}}_{\theta,n}(\mathsf{u}_n(z,t,h))=\mathsf{a}_{\theta}(x_{\star},z,t)$ and $\overline{\mathsf{b}}_{\theta,n}(\mathsf{u}_n(z,t,h))=\mathsf{b}_{\theta}(x_{\star},z,t)$.
Since $\mathcal{U}_{\mathrm{feat}}$ has bounded diameter and $\beta'\le1$, the state--time Lipschitz bounds are also $\beta'$-H\"older after increasing their constant.
This proves all claims of the lemma.

\label{prop:episode-kl-score-approximation}
Under \cref{assump:smooth-latent-task}, fix an integer $J\ge1$, pairwise distinct grid points $\theta_1,\ldots,\theta_J\in{\mathcal{T}}$, and $\eta\ge0$, and let $\pi_{\eta}:{\mathcal{T}}\to\{\theta_1,\ldots,\theta_J\}$ be Borel with $\|\theta-\pi_{\eta}(\theta)\|_2\le\eta$ for every $\theta$.
Set $w_j=\Pr\!\bigl(\pi_{\eta}(\Theta)=\theta_j\bigr)$ and, for $\zeta\in[0,1]$, set
\begin{equation}
 w_j^{\zeta}:=\frac{w_j+\zeta/J}{1+\zeta}.
 \label{eq:integrated-prior-weights}
\end{equation}
Let $Q^{\eta,\zeta}_{\mathrm{epi}}$ be the observed-episode distribution obtained by drawing a grid task with weights $w_j^{\zeta}$ and then drawing $n+1$ conditionally independent examples from $g_{\theta_j}$.
In the input--output model, an example is a full pair $(X,Z)$ and the observed episode is $(C_n,X_\star,Z_\star)$.
Because every grid density is positive, let $Q^{\eta,\zeta}_{0\mid h}$ denote the everywhere-defined Bayes conditional law of $Z_\star$ given $H_n=h$ under $Q^{\eta,\zeta}_{\mathrm{epi}}$.
If $q_t^{\eta,\zeta}(\cdot\mid h)$ denotes its OU-smoothed density, define
$s^{\eta,\zeta}(z,t\mid h):=\nabla_z\log q_t^{\eta,\zeta}(z\mid h)$.
Define $D_n(\eta,\zeta)=(n+1)H_\theta^2\eta^{2\beta_\theta}/\underline{p}+\log(1+\zeta)$.
Then
\begin{align}
 \mathrm{KL}\!\left({\mathbb{P}}_{\mathrm{epi}}^{(n)}\middle\|Q^{\eta,\zeta}_{\mathrm{epi}}\right)
 &\le D_n(\eta,\zeta), \label{eq:integrated-episode-kl}\\
 {\mathbb{E}}_{H_n}\mathrm{KL}(P_{0\mid H_n}\|Q^{\eta,\zeta}_{0\mid H_n})
 &\le D_n(\eta,\zeta). \label{eq:integrated-predictive-kl}
\end{align}
Moreover, for every $0<t_0<T<\infty$,
\begin{equation}
 \int_{t_0}^T{\mathbb{E}}\left[
 \|s^\star(Z_t,t\mid H_n)-s^{\eta,\zeta}(Z_t,t\mid H_n)\|_2^2\right]\,{\mathrm{d}} t
 \le D_n(\eta,\zeta), \label{eq:integrated-latent-score-bound}
\end{equation}
where $(H_n,Z_t)$ has the original prompt and conditional diffusion law.
The result is uniform over Borel task priors, including priors with zero cell masses.

\label{def:smooth-latent-score-class}
Fix $n$ and a latent grid, and choose tolerances
\begin{equation*}
 \varepsilon_{\mathrm{floor},n},\ \varepsilon_{\ell,n},\
 \varepsilon_{a,n},\ \varepsilon_{b,n},\
 \varepsilon_{\mathrm{rat},n}\in(0,1].
\end{equation*}
Also fix a deterministic final output radius $0<R_{\mathrm{out},n}\le R_{\mathrm{bal},n}$.
The radius $R_{\mathrm{bal},n}$ remains the uniform bound used for latent quadrature and internal basis estimates; $R_{\mathrm{out},n}$ controls the score-network output and the training loss.
In the input--output prompt model, also fix $\varepsilon_{\mathrm{qry},n}\in(0,1]$; in the sample-only prompt model, set $\varepsilon_{\mathrm{qry},n}:=0$ and omit the query factor below.
Index the context-example tokens by $I_{\mathrm{ctx}}:=\{1,\ldots,n\}$ and the latent tokens by $I_{\mathrm{lat}}:=\{i_1^{\mathrm{lat}},\ldots,i_{J_{\theta,n}}^{\mathrm{lat}}\}$.
Let $i_{\mathrm{sum}}$, $i_{\mathrm{qry}}$, $i_{\mathrm{out}}$, and $i_{\varnothing}$ denote the summary, query--state--time, output, and null tokens, respectively.
Thus the sequence has $n+J_{\theta,n}+4$ positions.
Choose the explicit token width in \cref{eq:smooth-latent-explicit-token-width}, namely
\begin{equation*}
  d_{\mathrm{emb},n}^{\mathrm{lat}}
  =(d_z+5)J_{\theta,n}+d_{\mathrm{stat}}+2d_z+11
  \le C_{d_z}\{J_{\theta,n}+d_{\mathrm{stat}}+1\}.
\end{equation*}
\emph{Trainable parameter space.}
Let ${\mathcal{V}}_n^{\mathrm{fit}}$ be the product of the compact parameter cubes for the likelihood approximators with bounded outputs in \cref{lem:fixed-dimensional-holder-relu-approximation}, the time-local OU-basis approximators in \cref{lem:smooth-latent-time-local-basis}, and the prior logits with radius \cref{eq:smooth-latent-prior-logit-radius}.
For attention, include every entry of each of the sixteen matrices
\begin{equation*}
 W_{Q,k},W_{K,k},W_{V,k},W_{O,k}\in
 [-B_{\mathrm{att},n},B_{\mathrm{att},n}]^{d_{\mathrm{emb},n}^{\mathrm{lat}}\times d_{\mathrm{emb},n}^{\mathrm{lat}}},
 \quad 1\le k\le4,
\end{equation*}
\begin{equation*}
 B_{\mathrm{att},n}=1\vee\sqrt{d_{\mathrm{emb},n}^{\mathrm{lat}}}.
\end{equation*}
Thus the attention part has exactly $16(d_{\mathrm{emb},n}^{\mathrm{lat}})^2$ trainable coordinates.
The sparse matrices in \cref{tab:smooth-latent-four-block-construction} specify a reference parameter within this entire score class.
The table describes the computation at that parameter; arbitrary trainable projections need not preserve its internal posterior interpretation or role coordinates.
The hard masks and coordinate-update maps are fixed for the entire class.
The query log-likelihood factor is omitted in the sample-only prompt model.
The fixed approximator architecture, latent identifiers, role codes, hard masks, coordinate-update maps, ratio readout, and radial output projection are not coordinates of ${\mathcal{V}}_n^{\mathrm{fit}}$.
Let $\mathsf{N}_{\mathrm{param},n}^{\mathrm{lat}}:=\dim({\mathcal{V}}_n^{\mathrm{fit}})$, let $B_{\mathrm{lat},n}\ge1$ dominate its coordinate radii, and let
\begin{equation*}
  \mathrm{Proj}_n^{\mathrm{par}}:
  [-B_{\mathrm{lat},n},B_{\mathrm{lat},n}]^{\mathsf{N}_{\mathrm{param},n}^{\mathrm{lat}}}
  \longrightarrow{\mathcal{V}}_n^{\mathrm{fit}}
\end{equation*}
be coordinatewise projection onto the corresponding factor ranges.
This map is continuous, nonexpansive in $\ell_{\infty}$, and onto.

\emph{Token representation.}
For a parameter vector $\mathbf{v}$ in the displayed cube, put $\widehat{\mathbf{v}}:=\mathrm{Proj}_n^{\mathrm{par}}(\mathbf{v})$.
We identify ${\mathcal{V}}_n^{\mathrm{fit}}$ with its natural subset of the enclosing cube; on this subset, $\mathrm{Proj}_n^{\mathrm{par}}$ is the identity.
Let $\mathbf{E}_n^{(0)}(\widehat{\mathbf{v}};z,t,h)$ be the encoded array of the $n$ context-example tokens, one summary token, one query--state--time token, $J_{\theta,n}$ latent tokens, one output token, and one null token.
In particular, every trainable component encoder is evaluated at the projected parameter vector $\widehat{\mathbf{v}}$.
The network-component specification in Appendix~\ref{app:subsubsec:transformer-construction} gives the initial value and shape of every token type, with ordered coordinate decomposition \cref{eq:smooth-latent-token-block-decomposition}.
The context-example network uses the fixed affine rescaling $c\mapsto2c-\mathbf{1}_{d_{\mathrm{stat}}}$.
In the input--output prompt model, the query log-likelihood network uses $x_{\star}\mapsto2x_{\star}-\mathbf{1}_{d_x}$.
The OU-basis network uses the globally bounded feature $\mathsf{u}_n(z,t,h)$ from \cref{eq:transformer-input-preprocessing}.
Its fixed time-local encoder combines overlapping time patches with a continuous ReLU partition of unity, as specified in Lemma~\ref{lem:smooth-latent-time-local-basis}; the four attention blocks are unchanged.
All occurrences of the noisy state in this encoded array use $\bar{z}={\mathrm{clip}}_{R_{\mathrm{state},n}}(z)$; there is no unprocessed state input.
Consequently, for every parameter in the class,
\begin{equation}
 \widetilde{s}_{\mathbf{v}}(z,t,h)=\widetilde{s}_{\mathbf{v}}(\bar{z},t,h).
 \label{eq:global-state-clipping-reduction}
\end{equation}
This identity reduces the full-state supremum in $d_{\mathrm{bal},\infty}$ to the compact state ball.
We suppress the common arguments $(\widehat{\mathbf{v}};z,t,h)$ from the token arrays in the recursion below.

\emph{Attention blocks.}
For $1\le k\le4$ and every token row $i$, define
\begin{equation}
  \mathbf{E}_{n,i}^{(k)}
  :=
  \mathsf{R}_{k,n}\!\left[
  \mathbf{E}_{n,i}^{(k-1)}
  {}+
  \operatorname{Att}_{\mathbf{A}_k(\widehat{\mathbf{v}})}
  \!\left(
  \mathbf{E}_{n,i}^{(k-1)};
  (\mathbf{E}_{n,j}^{(k-1)})_{j\in\mathsf{M}_{k,n}(i)}
  \right)
  \right].
  \label{eq:smooth-latent-score-class-recursion}
\end{equation}
Here $\mathbf{A}_k(\widehat{\mathbf{v}})$ denotes the four dense bounded attention projection matrices, and $\mathsf{R}_{k,n}$ is the fixed affine--ReLU coordinate-update map after block $k$.
The non-null masks are
\begin{equation*}
  \mathsf{M}_{1,n}(i_{\mathrm{sum}})=I_{\mathrm{ctx}},
  \qquad
  \mathsf{M}_{2,n}(i_j^{\mathrm{lat}})=\{i_{\mathrm{sum}}\},
  \qquad
  \mathsf{M}_{3,n}(i_j^{\mathrm{lat}})=\{i_{\mathrm{qry}}\},
  \qquad
  \mathsf{M}_{4,n}(i_{\mathrm{out}})=I_{\mathrm{lat}},
\end{equation*}
for $i_j^{\mathrm{lat}}\in I_{\mathrm{lat}}$, and every undeclared row attends only to $i_{\varnothing}$.
The projection matrices of the constructed network, residual destinations, and states after $\mathsf{R}_{k,n}$ are listed in \cref{tab:smooth-latent-four-block-construction}; bounded coordinatewise projection precedes the exact selector in \cref{eq:appendix-smooth-latent-binary-gate}.

\emph{Score readout and class.}
Let $\mathsf{Read}_n$ first apply exact coordinatewise projection onto
\begin{equation*}
 [\underline{q}_{\mathrm{out}},\overline{q}_{\mathrm{out}}]\times
 [-R_{\mathrm{num},n}^{\mathrm{lat}}-1,R_{\mathrm{num},n}^{\mathrm{lat}}+1]^{d_z},
\end{equation*}
and then apply the fixed affine normalization and ReLU ratio approximator constructed below.
This preliminary projection is part of the readout for every parameter; it is inactive on the reference network's averaged features.
Let $\mathsf{P}_{\mathrm{out}}$ extract the output-token coordinates.
Define
\begin{equation}
  \widetilde{s}_{\mathbf{v}}(z,t,h)
  :=
  {\mathrm{clip}}_{R_{\mathrm{out},n}}
  \!\left[
  \mathsf{Read}_n\!\left(
  \mathsf{P}_{\mathrm{out}}\mathbf{E}_n^{(4)}(\widehat{\mathbf{v}};z,t,h)
  \right)
  \right],
  \qquad
  s_{\mathbf{v}}(z,t,h):=\frac{\widetilde{s}_{\mathbf{v}}(z,t,h)}{\sigma_t},
  \label{eq:smooth-latent-score-class-output}
\end{equation}
and set
\begin{equation}
  {\mathcal{S}}_n^{\mathrm{lat}}
  :=
  \left\{
  s_{\mathbf{v}}:
  \mathbf{v}\in
  [-B_{\mathrm{lat},n},B_{\mathrm{lat},n}]^{\mathsf{N}_{\mathrm{param},n}^{\mathrm{lat}}}
  \right\}.
  \label{eq:smooth-latent-score-class-formal}
\end{equation}
Writing $\mathbf{A}_k(\widehat{\mathbf{v}})=(W_{Q,k},W_{K,k},W_{V,k},W_{O,k})$, the attention map in \cref{eq:smooth-latent-score-class-recursion} is $\operatorname{Att}_{W_{Q,k},W_{K,k},W_{V,k},W_{O,k}}$ from \cref{lem:attention-parameter-sensitivity} restricted to the displayed deterministic mask.
Here ``Transformer'' means the explicitly defined prompt-conditioned architecture: external ReLU input and readout modules surround four hard-masked residual softmax-attention blocks with fixed affine--ReLU coordinate updates and no layer normalization.
Exact containment in a fixed-width conventional Transformer with mandatory feed-forward sublayers or layer normalization is not claimed.
In particular, the definition does not cover a standard pre-normalized or post-normalized Transformer with fully learned coordinate updates.

\label{lem:smooth-latent-four-block-construction}
For the encoded array above, there exist four deterministic nonempty masks, projection matrices for the constructed network
\begin{equation*}
  W_{Q,k},W_{K,k},W_{V,k},W_{O,k}
  \in{\mathbb{R}}^{d_{\mathrm{emb},n}^{\mathrm{lat}}\times d_{\mathrm{emb},n}^{\mathrm{lat}}},
  \qquad 1\le k\le4,
\end{equation*}
and shared rowwise affine--ReLU maps
\begin{equation*}
  \mathsf{R}_{k,n}:{\mathbb{R}}^{d_{\mathrm{emb},n}^{\mathrm{lat}}}\to{\mathbb{R}}^{d_{\mathrm{emb},n}^{\mathrm{lat}}}
\end{equation*}
such that each residual block maps ${\mathbb{R}}^{(n+J+4)\times d_{\mathrm{emb},n}^{\mathrm{lat}}}$ to itself and implements the computation in \cref{tab:smooth-latent-four-block-construction}.
Every row not listed in that table attends only to the null token.
After block 4, the output block equals
\begin{equation}
  \left(
  \sum_{j=1}^J\widehat{\omega}_{j,n}\widehat{\mathsf{a}}_j,
  \sum_{j=1}^J\widehat{\omega}_{j,n}\widehat{\mathsf{b}}_j
  \right)\in\mathsf{V}_{\mathrm{out}},
  \qquad
  \widehat{\omega}_{j,n}
  =\operatorname{softmax}_j((\widehat{\ell}_{k,n}^{\mathrm{post}})_{k=1}^{J}),
  \label{eq:smooth-latent-four-block-output}
\end{equation}
where
\begin{equation}
  \widehat{\ell}_{j,n}^{\mathrm{post}}
  =\ell_{j,n}^{\mathrm{prior}}
  +n\overline{\widehat{\ell}}_j
  +\widehat{\ell}_j^{\mathrm{qry}},
  \qquad
  \overline{\widehat{\ell}}_j
  :=\frac{1}{n}\sum_{i=1}^n\widehat{\ell}_j(c_i).
  \label{eq:smooth-latent-posterior-logit-update}
\end{equation}
The four residual updates preserve all role codes and latent identifiers.
Every projection and coordinate-update coefficient of the constructed network has magnitude at most
\begin{equation*}
  1\vee n\vee B_{\mathrm{gate},n}^{\mathrm{lat}}
  \vee\sqrt{d_{\mathrm{emb},n}^{\mathrm{lat}}},
\end{equation*}
where $B_{\mathrm{gate},n}^{\mathrm{lat}}$ is defined in \cref{eq:smooth-latent-selector-radius}.
Hence the construction is an explicit member of the score class in \cref{def:smooth-latent-score-class}.

\label{lem:attention-parameter-sensitivity}
Fix $B\ge1$.
Suppose every entry of the tokens and matrices in this attention map and in a primed copy is bounded in absolute value by $B$.
Let $\eta_{\mathrm{att}}$ be the maximum of the entrywise matrix differences and the $\ell_{\infty}$ distances between corresponding tokens.
Then
\begin{equation*}
  \left\|
  \operatorname{Att}_{W_Q,W_K,W_V,W_O}(v;x_{1:m})
  -\operatorname{Att}_{W'_Q,W'_K,W'_V,W'_O}(v';x'_{1:m})
  \right\|_{\infty}
  \le16d^5B^6\eta_{\mathrm{att}}.
\end{equation*}
The bound is independent of the number of keys $m$ and remains valid after restricting both maps by the same deterministic nonempty attention mask.

The matrix inequality $\|Ax\|_{\infty}\le d\|A\|_{\max}\|x\|_{\infty}$ gives
\begin{equation*}
  \|W_Qv-W'_Qv'\|_{\infty}
  +\max_j\|W_Kx_j-W'_Kx_j'\|_{\infty}
  \le4dB\eta_{\mathrm{att}}.
\end{equation*}
A two-term telescoping argument for the scaled dot products therefore gives
\begin{equation*}
  \max_j\left|
  \frac{(W_Qv)^{\top} W_Kx_j-(W'_Qv')^{\top} W'_Kx_j'}{\sqrt{d}}
  \right|
  \le4d^{5/2}B^3\eta_{\mathrm{att}}.
\end{equation*}
The softmax map satisfies the following Lipschitzness~\citep[Corollary A.7]{edelman22a}:
\begin{equation*}
  \|\operatorname{softmax}(a)-\operatorname{softmax}(a')\|_1
  \le2\|a-a'\|_{\infty}.
\end{equation*}
The weighted value average consequently changes by at most
\begin{equation*}
  \left\|
  \sum_j\pi_jW_Vx_j-
  \sum_j\pi_j'W'_Vx_j'
  \right\|_{\infty}
  \le\{8d^{7/2}B^5+2dB\}\eta_{\mathrm{att}}.
\end{equation*}
One final telescoping step through $W_O$ yields
\begin{equation*}
  \|W_O-W'_O\|_{\max}\left\|\sum_j\pi_jW_Vx_j\right\|_1
  +dB\left\|\sum_j\pi_jW_Vx_j-\sum_j\pi_j'W'_Vx_j'\right\|_{\infty}
  \le16d^5B^6\eta_{\mathrm{att}}.
\end{equation*}
Applying the same argument to the restricted list of keys selected by the common mask proves the masked version.

\label{lem:fixed-dimensional-holder-relu-approximation}
Fix $d,d_{\mathrm{out}}\in\mathbb{N}$ and $\beta_0\in(0,1]$.
There is an exponent $0<c<\infty$, depending only on $(d,d_{\mathrm{out}},\beta_0)$, with the following property; all implicit constants below have the same allowed dependencies.
Let $M_f,H\ge0$, let $\varepsilon\in(0,1]$, and let $f:[-1,1]^d\to[-M_f,M_f]^{d_{\mathrm{out}}}$ satisfy
\begin{equation*}
  \|f(x)-f(x')\|_{\infty}
  \le H\|x-x'\|_{\infty}^{\beta_0}.
\end{equation*}
There are integers $D_{\varepsilon}^{\mathrm{NN}},W_{\varepsilon},S_{\varepsilon}\ge1$, a bound $B_{\varepsilon}\ge1$, and a fixed-architecture class
\begin{equation*}
  \mathscr{N}_{\varepsilon}
  \subseteq
  \mathrm{Proj}_{[-M_f,M_f]^{d_{\mathrm{out}}}}\circ
  {\mathcal{NN}}(D_{\varepsilon}^{\mathrm{NN}},W_{\varepsilon},S_{\varepsilon},B_{\varepsilon}),
\end{equation*}
chosen independently of $f$, that contains a member $f_{\varepsilon}$ satisfying
\begin{equation*}
  \sup_{x\in[-1,1]^d}
  \|f_{\varepsilon}(x)-f(x)\|_{\infty}\le\varepsilon.
\end{equation*}
The network sizes satisfy
\begin{equation}
  D_{\varepsilon}^{\mathrm{NN}}\vee W_{\varepsilon}\vee S_{\varepsilon}
  \lesssim
  \left(1+\frac{H\vee1}{\varepsilon}\right)^{d/\beta_0}
  \log^2\!\left(2+\frac{1+M_f+H}{\varepsilon}\right),
  \label{eq:fixed-dimensional-holder-network-size}
\end{equation}
Every scalar weight and bias has magnitude at most $B_{\varepsilon}$.
The tensor-hat and multiplication subnetworks are fixed, and only the output-layer interpolation coefficients vary over a compact cube.
After adding functionally inactive coordinates, write the class as
\begin{equation*}
  \mathscr{N}_{\varepsilon}
  =\{f_{\vartheta}:\vartheta\in[-B_{\varepsilon},B_{\varepsilon}]^{S_{\varepsilon}}\}.
\end{equation*}
The evaluation map $(x,\vartheta)\mapsto f_{\vartheta}(x)$ is jointly Borel and continuous in $\vartheta$.
There are constants $\mathsf{Lip}_{\mathrm{par}},\mathsf{Lip}_{\mathrm{in}}\in[0,\infty)$ such that
\begin{align*}
  \sup_x\|f_{\vartheta}(x)-f_{\vartheta'}(x)\|_{\infty}
  &\le \mathsf{Lip}_{\mathrm{par}}\|\vartheta-\vartheta'\|_{\infty},
  \\
  \sup_{\vartheta\in[-B_{\varepsilon},B_{\varepsilon}]^{S_{\varepsilon}}}
  \|f_{\vartheta}(x)-f_{\vartheta}(x')\|_{\infty}
  &\le \mathsf{Lip}_{\mathrm{in}}\|x-x'\|_{\infty},
\end{align*}
and
\begin{equation}
  B_{\varepsilon}+\mathsf{Lip}_{\mathrm{par}}+\mathsf{Lip}_{\mathrm{in}}
  \lesssim (1+M_f+H+\varepsilon^{-1})^c.
  \label{eq:fixed-dimensional-holder-parameter-stability}
\end{equation}

Affinely rescale the input cube to $[0,1]^d$ and take a regular tensor grid with mesh
\begin{equation*}
  \eta_{\mathrm{grid}}:=\min\left\{1,
  c_d\left(\frac{\varepsilon}{H\vee1}\right)^{1/\beta_0}\right\},
\end{equation*}
where $c_d>0$ is chosen below.
If $u_1,\ldots,u_{J_{\mathrm{hat}}}$ are the grid points and $\psi_1,\ldots,\psi_{J_{\mathrm{hat}}}$ the tensor-hat partition of unity, then $J_{\mathrm{hat}}\le C_d\{1+(H\vee1)/\varepsilon\}^{d/\beta_0}$.
The interpolant
\begin{equation*}
  I_{\eta_{\mathrm{grid}}}f(x):=\sum_{j=1}^{J_{\mathrm{hat}}} f(u_j)\psi_j(x)
\end{equation*}
satisfies $\|I_{\eta_{\mathrm{grid}}}f-f\|_{\infty}\le H(C_d\eta_{\mathrm{grid}})^{\beta_0}\le\varepsilon/2$ after decreasing $c_d$.

Every univariate hat is an exact ReLU function.
Use the ReLU multiplication construction in \citet[Proposition~3 and its proof]{yarotsky2017} on a fixed bounded interval, recursively approximate each product of $d$ univariate hats, and project the result onto $[0,1]$.
With
\begin{equation*}
  \varepsilon_{\mathrm{mult}}:=\frac{\varepsilon}{2J_{\mathrm{hat}}(M_f\vee1)},
\end{equation*}
each approximate tensor hat $\widehat{\psi}_j$ can be chosen so that $\|\widehat{\psi}_j-\psi_j\|_{\infty}\le\varepsilon_{\mathrm{mult}}$.
Consequently,
\begin{equation*}
  \left\|
  \sum_{j=1}^{J_{\mathrm{hat}}}f(u_j)\widehat{\psi}_j-I_{\eta_{\mathrm{grid}}}f
  \right\|_{\infty}
  \le J_{\mathrm{hat}}M_f\varepsilon_{\mathrm{mult}}\le\varepsilon/2.
\end{equation*}
The multiplication paths have fixed width and depth ${\mathcal{O}}_d\!\left(\log(2+\varepsilon_{\mathrm{mult}}^{-1})\right)$.
Parallelizing the $J_{\mathrm{hat}}$ subnetworks gives a fixed wiring pattern whose depth, width, and total number of scalar weights and biases obey \cref{eq:fixed-dimensional-holder-network-size}; the extra logarithm allows all coordinates to share one network graph.
Fix every hat and multiplication weight at the value used in these $J_{\mathrm{hat}}$ approximate basis functions.
For a coefficient array $\mathbf{a}=(a_{kj})_{1\le k\le d_{\mathrm{out}},1\le j\le J_{\mathrm{hat}}}$, define
\begin{equation*}
  \widetilde{f}_{\mathbf{a}}(x)
  :=\left(\sum_{j=1}^{J_{\mathrm{hat}}} a_{kj}\widehat{\psi}_j(x)\right)_{k=1}^{d_{\mathrm{out}}},
  \qquad
  f_{\mathbf{a}}:=\mathrm{Proj}_{[-M_f,M_f]^{d_{\mathrm{out}}}}\circ\widetilde{f}_{\mathbf{a}}.
\end{equation*}
Choose $B_{\varepsilon}$ to bound the fixed network weights, the hat slopes, and the coefficient range $[-B_{\varepsilon},B_{\varepsilon}]^{d_{\mathrm{out}}J_{\mathrm{hat}}}$, with $B_{\varepsilon}\ge M_f$.
Only $\mathbf{a}$ is variable; all internal network parameters are fixed and therefore are not trainable.
Pad $\mathbf{a}$ by inactive coordinates to obtain a parameter vector $\vartheta\in[-B_{\varepsilon},B_{\varepsilon}]^{S_{\varepsilon}}$.
The resulting class and its fixed wiring depend only on $(d,d_{\mathrm{out}},\beta_0,M_f,H,\varepsilon)$ and not on $f$.
Taking $a_{kj}=f_k(u_j)$ gives the approximant established above.

Because $0\le\widehat{\psi}_j\le1$ and Euclidean projection onto the box is nonexpansive,
\begin{equation*}
  \sup_x\|f_{\mathbf{a}}(x)-f_{\mathbf{a}'}(x)\|_{\infty}
  \le J_{\mathrm{hat}}\|\mathbf{a}-\mathbf{a}'\|_{\infty}.
\end{equation*}
Thus one may take $\mathsf{Lip}_{\mathrm{par}}=J_{\mathrm{hat}}$.
Each exact univariate hat is $C_d\eta_{\mathrm{grid}}^{-1}$-Lipschitz.
The multiplication paths have fixed width, uniformly bounded weights, and depth ${\mathcal{O}}_d(\log(2+\varepsilon_{\mathrm{mult}}^{-1}))$.
Write $\operatorname{Lip}_{\infty}(g)$ for the Lipschitz constant of a map $g$ with respect to the $\ell_{\infty}$ norm.
For a constant $\kappa_d>0$ depending only on $d$, the layerwise operator-norm bound gives
\begin{equation*}
  \max_{1\le j\le J_{\mathrm{hat}}}\operatorname{Lip}_{\infty}(\widehat{\psi}_j)
  \le C_d\eta_{\mathrm{grid}}^{-1}(2+\varepsilon_{\mathrm{mult}}^{-1})^{\kappa_d}
  =:\mathsf{Lip}_{\psi,\varepsilon}.
\end{equation*}
Consequently, uniformly over the coefficient cube,
\begin{equation*}
  \|f_{\mathbf{a}}(x)-f_{\mathbf{a}}(x')\|_{\infty}
  \le J_{\mathrm{hat}}B_{\varepsilon}\mathsf{Lip}_{\psi,\varepsilon}\|x-x'\|_{\infty}.
\end{equation*}
Hence one may take $\mathsf{Lip}_{\mathrm{in}}=J_{\mathrm{hat}}B_{\varepsilon}\mathsf{Lip}_{\psi,\varepsilon}$.
The quantities $J_{\mathrm{hat}}$, $\eta_{\mathrm{grid}}^{-1}$, $\varepsilon_{\mathrm{mult}}^{-1}$, and $B_{\varepsilon}$ are polynomial in $(1+M_f+H+\varepsilon^{-1})$ because $d$ is fixed.
This proves \cref{eq:fixed-dimensional-holder-parameter-stability}.
All remaining measurability and continuity claims follow from finite continuous composition.

\label{lem:smooth-latent-time-local-basis}
Under \cref{assump:smooth-latent-task}, use the constants from \cref{lem:positive-smooth-latent-derived-regularity}, and fix $0<t_0<T$, the state radius, and $\varepsilon_{a,n},\varepsilon_{b,n}\in(0,1]$.
Define
\begin{equation*}
 K:=\max\{1,\lfloor\log_2(T/t_0)\rfloor\},\qquad
 t_j^{\mathrm{knot}}:=2^jt_0\ (0\le j<K),\qquad t_K^{\mathrm{knot}}:=T.
\end{equation*}
For $0\le j\le K$, set
\begin{equation*}
 a_j:=t_{\max\{0,j-1\}}^{\mathrm{knot}},\qquad
 b_j:=t_{\min\{K,j+1\}}^{\mathrm{knot}},\qquad
 h_j^{\mathrm{loc}}:=b_j-a_j.
\end{equation*}
Let $R_{\mathrm{geom},n}:=1+R_{\mathrm{state},n}+\sqrt{d_z}$, and fix a sufficiently large constant $C_{\mathrm{loc}}$ depending only on the fixed dimensions, $\beta'$, and the common density bounds.
Apply the extension construction of \cref{lem:smooth-latent-normalized-basis-regularity} on each interval, using the query and state normalization in \cref{eq:transformer-input-preprocessing} and affine normalization of the local time interval to $[-1,1]$.
The resulting denominator and numerator maps have respective $\beta'$-H\"older moduli bounded by
\begin{align}
 H_{a,j,n}
 &:=C_{\mathrm{loc}}\big[
 1+H_{q,x}
 +R_{\mathrm{state},n}R_{\mathrm{geom},n}\sigma_{a_j}^{-2}
 +h_j^{\mathrm{loc}}R_{\mathrm{geom},n}^2\sigma_{a_j}^{-4}\big],
 \label{eq:smooth-latent-local-denominator-modulus}\\
 H_{b,j,n}
 &:=C_{\mathrm{loc}}\big[
 1+R_{\mathrm{bal},n}H_{q,x}
 +R_{\mathrm{state},n}
   \{\sigma_{a_j}^{-1}+R_{\mathrm{geom},n}^2\sigma_{a_j}^{-3}\}
 \nonumber\\
 &\hspace{18mm}
 +h_j^{\mathrm{loc}}\{\sigma_{a_j}^{-1}
 +R_{\mathrm{geom},n}\sigma_{a_j}^{-3}
 +R_{\mathrm{geom},n}^3\sigma_{a_j}^{-5}\}\big].
 \label{eq:smooth-latent-local-numerator-modulus}
\end{align}
Write
\begin{equation*}
 H_{\max,n}:=\max_{0\le j\le K}(H_{a,j,n}\vee H_{b,j,n}),
\end{equation*}
and
\begin{equation*}
 L_{\mathrm{bas},n}
 :=\log\!\left(
 2+K+\frac{1+R_{\mathrm{num},n}^{\mathrm{lat}}+H_{\max,n}}
 {\varepsilon_{a,n}\wedge\varepsilon_{b,n}}
 \right).
\end{equation*}
For each latent-grid point, there is a shared fixed-architecture ReLU class containing approximations with uniform errors at most $\varepsilon_{a,n}$ for $\mathsf{a}$ and $\varepsilon_{b,n}$ in Euclidean norm for $\mathsf{b}$ on $\mathcal{G}_n$.
Across all $J_{\theta,n}$ points, the number of trainable parameters, number of stored nonzero coefficients, and evaluation cost are bounded by
\begin{equation}
 \mathsf{N}_{\mathrm{basis},n}^{\mathrm{lat}}
 :=C_{\mathrm{loc}} J_{\theta,n}L_{\mathrm{bas},n}^2
 \sum_{j=0}^K\left[
 \left(1+\frac{H_{a,j,n}}{\varepsilon_{a,n}}\right)^{(d_{\mathrm{stat}}+1)/\beta'}
 +d_z\left(1+\frac{H_{b,j,n}}{\varepsilon_{b,n}}\right)^{(d_{\mathrm{stat}}+1)/\beta'}
 \right].
 \label{eq:smooth-latent-time-local-basis-size}
\end{equation}
Every member is projected onto $[\underline{q}_{\mathrm{out}},\overline{q}_{\mathrm{out}}]$ in its denominator coordinate and onto $[-R_{\mathrm{num},n}^{\mathrm{lat}}-1,R_{\mathrm{num},n}^{\mathrm{lat}}+1]$ in each numerator coordinate.
Only output-layer interpolation coefficients are trainable; they range over a compact cube, with inactive padding coordinates allowed.
The parameter radius and the input and parameter Lipschitz constants are polynomial in
\begin{equation*}
 1+K+T+t_0^{-1}+R_{\mathrm{state},n}
 +R_{\mathrm{num},n}^{\mathrm{lat}}+H_{\max,n}
 +(\varepsilon_{a,n}\wedge\varepsilon_{b,n})^{-1}.
\end{equation*}
The class depends only on the displayed common quantities, not on the task map or task prior.

\label{lem:smooth-latent-output-clipping}
For a deterministic radius $R_{\mathrm{out},n}>0$, set
\begin{equation}
 \varepsilon_{\mathrm{out,clip},n}^2
 :=A_{t_0,T}{\mathbb{E}}(\|\xi\|_2-R_{\mathrm{out},n})_{+}^2,
 \qquad \xi\sim{\mathcal{N}}(0,I_{d_z}).
 \label{eq:smooth-latent-output-clipping-error}
\end{equation}
Under the episodic OU model,
\begin{equation}
 {\mathbb{E}}_{H_n}\int_{t_0}^T
 \frac{{\mathbb{E}}_{Z_t\mid H_n}
 \|\widetilde{s}^{\star}(Z_t,t\mid H_n)
 -{\mathrm{clip}}_{R_{\mathrm{out},n}}\widetilde{s}^{\star}(Z_t,t\mid H_n)\|_2^2}
 {\sigma_t^2}\,{\mathrm{d}} t
 \le\varepsilon_{\mathrm{out,clip},n}^2.
 \label{eq:smooth-latent-output-clipping-bias}
\end{equation}
If $R_{\mathrm{out},n}\ge\sqrt{d_z}$, then
\begin{equation}
 \varepsilon_{\mathrm{out,clip},n}^2
 \le2A_{t_0,T}
 \exp\!\left\{-\tfrac{1}{2}(R_{\mathrm{out},n}-\sqrt{d_z})^2\right\}.
 \label{eq:smooth-latent-output-clipping-tail}
\end{equation}

\label{prop:integrated-transformer-approximation}
Use the regular grid and cell-midpoint map from \cref{app:subsec:latent-quadrature}, set $\eta=\eta_{\theta,n}$ and $\zeta=\varepsilon_{\mathrm{floor},n}>0$ in \cref{prop:episode-kl-score-approximation}, and use the class in \cref{def:smooth-latent-score-class}.
Let $\varepsilon_{\mathrm{net},n}$ be the component-error expression in \cref{app:subsec:shared-neural-estimates}.
Then
\begin{align}
 {\mathcal{E}}_{\mathrm{app}}({\mathcal{S}}_n^{\mathrm{lat}})
 \le {}&4D_n(\eta_{\theta,n},\varepsilon_{\mathrm{floor},n})
       +4A_{t_0,T}\varepsilon_{\mathrm{net},n}^2
       +2\varepsilon_{\mathrm{out,clip},n}^2 \nonumber\\
       &+2A_{t_0,T}R_{\mathrm{out},n}^2\delta_{\mathrm{tail},n}
       +2\varepsilon_{\mathrm{tail},n}^2.
 \label{eq:integrated-transformer-approximation}
\end{align}
The parameters of the approximating network may depend on the task family and prior.
Its architecture, coordinate bounds, and approximation guarantee depend only on the common bounds, grid, and tolerances.

\label{prop:smooth-latent-complexity}
Under \cref{assump:smooth-latent-task}, fix any regular latent grid and component tolerances satisfying \cref{def:smooth-latent-score-class}.
Let $\mathsf{N}_{\mathrm{param},n}^{\mathrm{lat}}$ count trainable scalar coordinates, let $\mathsf{N}_{\mathrm{store},n}^{\mathrm{lat}}$ count stored nonzero scalar coefficients under this convention, and let $\mathsf{N}_{\mathrm{op},n}^{\mathrm{lat}}$ count sparse arithmetic operations in one forward evaluation.
With the indexing in \cref{def:smooth-latent-score-class}, the score class has the compact trainable-parameter representation
\begin{equation*}
  {\mathcal{S}}_n^{\mathrm{lat}}
  =\{s_{\mathbf{v}}:\mathbf{v}\in[-B_{\mathrm{lat},n},B_{\mathrm{lat},n}]^{\mathsf{N}_{\mathrm{param},n}^{\mathrm{lat}}}\}.
\end{equation*}
There is a deterministic constant $\mathsf{Lip}_{\mathrm{lat},n}^{\mathrm{par}}$ such that
\begin{equation}
  d_{\mathrm{bal},\infty}(s_{\mathbf{v}},s_{\mathbf{v}'})
  \le
  \mathsf{Lip}_{\mathrm{lat},n}^{\mathrm{par}}
  \|\mathbf{v}-\mathbf{v}'\|_{\infty}.
  \label{eq:smooth-latent-parameter-sensitivity}
\end{equation}
This bound holds for all parameter vectors $\mathbf{v}$ and $\mathbf{v}'$ in the displayed cube.
Consequently, for every $\varepsilon_{\mathrm{cov}}>0$,
\begin{equation}
  \logN_{\mathrm{cov}}\!\left(
  \varepsilon_{\mathrm{cov}},{\mathcal{S}}_n^{\mathrm{lat}},d_{\mathrm{bal},\infty}
  \right)
  \le
  \mathsf{N}_{\mathrm{param},n}^{\mathrm{lat}}
  \log\!\left(
  1+\frac{2B_{\mathrm{lat},n}
  \mathsf{Lip}_{\mathrm{lat},n}^{\mathrm{par}}}{\varepsilon_{\mathrm{cov}}}
  \right).
  \label{eq:smooth-latent-score-cover}
\end{equation}
The empirical variance-balanced DSM loss admits a Borel-measurable exact ERM over this compact parameter cube.
Explicit bounds for $\mathsf{N}_{\mathrm{param},n}^{\mathrm{lat}}$, $\mathsf{N}_{\mathrm{store},n}^{\mathrm{lat}}$, and $\mathsf{N}_{\mathrm{op},n}^{\mathrm{lat}}$ are given in \cref{eq:smooth-latent-trainable-parameter-count,eq:smooth-latent-coefficient-storage,eq:smooth-latent-forward-cost}.
These conclusions hold uniformly over the task maps in the fixed regularity class of \cref{assump:smooth-latent-task} and every Borel task prior on ${\mathcal{T}}$.

\label{lem:smooth-latent-four-block-sensitivity}
Let $\mathbf{v},\mathbf{v}'\in{\mathcal{V}}_n^{\mathrm{fit}}$ collect trainable coordinates of the component networks, prior logits, and entries of the attention projection matrices.
All token-array bounds below hold uniformly over $(h,z,t)\in\mathcal{G}_n$, and their common input arguments are suppressed.
There are deterministic quantities $B_{0,n},\mathsf{Lip}_{0,n},B_{\mathrm{par},n}\ge1$ and fixed-map constants $B_{\mathrm{rt},k,n},\mathsf{Lip}_{\mathrm{rt},k,n}\ge1$, $1\le k\le4$, such that
\begin{align}
  \max_i\|\mathbf{E}_{n,i}^{(0)}(\mathbf{v})\|_{\infty}
  &\le B_{0,n},
  \label{eq:smooth-latent-initial-token-envelope}\\
  \max_i\|\mathbf{E}_{n,i}^{(0)}(\mathbf{v})-\mathbf{E}_{n,i}^{(0)}(\mathbf{v}')\|_{\infty}
  &\le \mathsf{Lip}_{0,n}\|\mathbf{v}-\mathbf{v}'\|_{\infty},
  \label{eq:smooth-latent-initial-token-sensitivity}
\end{align}
and every trainable or fixed coefficient used by an attention block has magnitude at most $B_{\mathrm{par},n}$.
Define recursively, for $1\le k\le4$,
\begin{align}
  \overline{B}_{k-1,n}
  &:=\max\{1,B_{\mathrm{par},n},B_{k-1,n}\},
  \nonumber\\
  B_{k,n}
  &:=B_{\mathrm{rt},k,n}\left\{1+B_{k-1,n}+(d_{\mathrm{emb},n}^{\mathrm{lat}})^2\overline{B}_{k-1,n}^3\right\},
  \label{eq:smooth-latent-recursion-envelope}\\
  \mathsf{Lip}_{k,n}
  &:=\mathsf{Lip}_{\mathrm{rt},k,n}\left[
  \mathsf{Lip}_{k-1,n}+16(d_{\mathrm{emb},n}^{\mathrm{lat}})^5\overline{B}_{k-1,n}^6(1+\mathsf{Lip}_{k-1,n})
  \right].
  \label{eq:smooth-latent-recursion-sensitivity}
\end{align}
Then, for every $0\le k\le4$,
\begin{align}
  \max_i\|\mathbf{E}_{n,i}^{(k)}(\mathbf{v})\|_{\infty}
  &\le B_{k,n},
  \label{eq:smooth-latent-token-envelope}\\
  \max_i\|\mathbf{E}_{n,i}^{(k)}(\mathbf{v})-\mathbf{E}_{n,i}^{(k)}(\mathbf{v}')\|_{\infty}
  &\le \mathsf{Lip}_{k,n}\|\mathbf{v}-\mathbf{v}'\|_{\infty}.
  \label{eq:smooth-latent-token-sensitivity}
\end{align}
The quantities $B_{0,n}$, $\mathsf{Lip}_{0,n}$, $B_{\mathrm{par},n}$, $B_{\mathrm{rt},k,n}$, and $\mathsf{Lip}_{\mathrm{rt},k,n}$ are polynomial in the displayed component-network bounds, $d_{\mathrm{emb},n}^{\mathrm{lat}}$, $J_{\theta,n}$, $B_{\mathrm{gate},n}^{\mathrm{lat}}$, and $\log(2J_{\theta,n}/\varepsilon_{\mathrm{floor},n})$.
If $\mathsf{Lip}_{\mathrm{out},n}$ is an input-Lipschitz constant of the fixed ratio readout followed by radial projection, then
\begin{equation}
  d_{\mathrm{bal},\infty}(s_{\mathbf{v}},s_{\mathbf{v}'})
  \le \mathsf{Lip}_{\mathrm{out},n}\mathsf{Lip}_{4,n}\|\mathbf{v}-\mathbf{v}'\|_{\infty},
  \label{eq:smooth-latent-four-block-final-sensitivity}
\end{equation}
and $\mathsf{Lip}_{\mathrm{out},n}$ is polynomial in the same inputs and $\varepsilon_{\mathrm{rat},n}^{-1}$.

The likelihood-network bounds in \cref{eq:fixed-dimensional-holder-parameter-stability}, the time-local basis bounds in Lemma~\ref{lem:smooth-latent-time-local-basis}, the projections of component outputs, and \cref{eq:smooth-latent-prior-logit-radius} give \cref{eq:smooth-latent-initial-token-envelope,eq:smooth-latent-initial-token-sensitivity} and a polynomial choice of $B_{\mathrm{par},n}$.
After each attention update, let $\mathsf{R}_{k,n}$ denote the fixed affine--ReLU coordinate-update map, with the selector from \cref{eq:appendix-smooth-latent-binary-gate} included after the third update.
The four coordinate-update networks have a universal depth bound $D_{\mathrm{rt}}$, width at most $C_{d_z}(d_{\mathrm{emb},n}^{\mathrm{lat}})^2$, and coefficient magnitude at most
\begin{equation*}
  B_{\mathrm{rt},n}
  :=1\vee n\vee B_{\mathrm{gate},n}^{\mathrm{lat}}
  \vee\sqrt{d_{\mathrm{emb},n}^{\mathrm{lat}}}.
\end{equation*}
An affine layer of width at most $w$ and coefficient bound $B$ satisfies
\begin{equation*}
  1+\|Wx+b\|_{\infty}\le2w(B\vee1)(1+\|x\|_{\infty}),
  \qquad
  \|W(x-x')\|_{\infty}\le w(B\vee1)\|x-x'\|_{\infty}.
\end{equation*}
ReLU is one-Lipschitz and does not increase the bound on token magnitudes, so iteration over the $D_{\mathrm{rt}}$ layers gives constants $B_{\mathrm{rt},k,n},\mathsf{Lip}_{\mathrm{rt},k,n}\ge1$ satisfying
\begin{align*}
  \|\mathsf{R}_{k,n}(x)\|_{\infty}
  &\le B_{\mathrm{rt},k,n}(1+\|x\|_{\infty}),\\
  \|\mathsf{R}_{k,n}(x)-\mathsf{R}_{k,n}(x')\|_{\infty}
  &\le \mathsf{Lip}_{\mathrm{rt},k,n}\|x-x'\|_{\infty}.
\end{align*}
More precisely, one may take both constants no larger than
\begin{equation*}
  \{2C_{d_z}(d_{\mathrm{emb},n}^{\mathrm{lat}})^2B_{\mathrm{rt},n}\}^{D_{\mathrm{rt}}}.
\end{equation*}
This proves the asserted polynomial dependence for the coordinate-update networks.
If the tokens and attention matrices entering block $k$ are bounded by $\overline{B}_{k-1,n}$, then its attention output is bounded coordinatewise by $(d_{\mathrm{emb},n}^{\mathrm{lat}})^2\overline{B}_{k-1,n}^3$.
Adding the residual and applying $\mathsf{R}_{k,n}$ proves \cref{eq:smooth-latent-recursion-envelope,eq:smooth-latent-token-envelope} by induction.
At block $k$, the maximum perturbation among its tokens and trainable matrices is at most $(1+\mathsf{Lip}_{k-1,n})\|\mathbf{v}-\mathbf{v}'\|_{\infty}$.
The attention perturbation bound in \cref{lem:attention-parameter-sensitivity}, followed by the residual update and the $\mathsf{Lip}_{\mathrm{rt},k,n}$-Lipschitz coordinate-update map, gives \cref{eq:smooth-latent-recursion-sensitivity,eq:smooth-latent-token-sensitivity}.
The preliminary readout projection maps all inputs to the compact approximation box specified above and is nonexpansive.
Thus \cref{eq:fixed-dimensional-holder-parameter-stability} gives a global polynomial input-Lipschitz constant for the fixed ratio readout; radial output projection is also nonexpansive.
The state-clipping identity \cref{eq:global-state-clipping-reduction} extends the token bounds from $\mathcal{G}_n$ to the full state domain.
Absorbing the fixed conversion between $\ell_{\infty}$ and Euclidean norms into $\mathsf{Lip}_{\mathrm{out},n}$ proves \cref{eq:smooth-latent-four-block-final-sensitivity}.

\label{prop:balanced-clipping-bias}
For every $R_{\mathrm{lab}} > 0$,
\begin{equation}
  \varepsilon_{\mathrm{lab,clip}}^2(R_{\mathrm{lab}})
  \le A_{t_0, T}{\mathbb{E}}(\|\xi\|_2-R_{\mathrm{lab}})_{+}^2,
  \qquad \xi \sim {\mathcal{N}}(0, I_{d_z}).
  \label{eq:balanced-clipping-bias-gaussian}
\end{equation}
Consequently, for every $x \ge 0$, taking $R_{\mathrm{lab}} \ge \sqrt{d_z}+x$ gives
\begin{equation}
  \varepsilon_{\mathrm{lab,clip}}^2(R_{\mathrm{lab}})
  \le 2A_{t_0, T}e^{-x^2/2}.
  \label{eq:balanced-clipping-bias}
\end{equation}

Let $\xi_{R_{\mathrm{lab}}}^{\mathrm{clip}}:={\mathrm{clip}}_{R_{\mathrm{lab}}}(-\xi_{\mathrm{dsm}})$.
By \cref{prop:balanced-dsm-identity}, $\widetilde{s}^{\star}(Z_{\tau},\tau\,|\, H_n)={\mathbb{E}}[-\xi_{\mathrm{dsm}}\,|\, Z_{\tau},\tau,H_n]$, whereas $\widetilde{s}_{R_{\mathrm{lab}}}^{\mathrm{lab}}(Z_{\tau},\tau,H_n)={\mathbb{E}}[\xi_{R_{\mathrm{lab}}}^{\mathrm{clip}}\,|\, Z_{\tau},\tau,H_n]$.
Conditional Jensen's inequality therefore gives
\begin{align*}
  \left\|\widetilde{s}_{R_{\mathrm{lab}}}^{\mathrm{lab}}
  (Z_{\tau},\tau,H_n)-\widetilde{s}^{\star}(Z_{\tau},\tau\,|\, H_n)
  \right\|_2^2
  &\le
  {\mathbb{E}}\!\left[
  \|\xi_{R_{\mathrm{lab}}}^{\mathrm{clip}}
  +\xi_{\mathrm{dsm}}\|_2^2 \,|\, Z_{\tau},\tau,H_n\right].
\end{align*}
For radial clipping, $\|{\mathrm{clip}}_R(u)-u\|_2 = (\|u\|_2-R)_{+}$.
Hence
\begin{equation*}
  \varepsilon_{\mathrm{lab,clip}}^2(R_{\mathrm{lab}})
  \le A_{t_0, T}{\mathbb{E}}(\|\xi_{\mathrm{dsm}}\|_2-R_{\mathrm{lab}})_{+}^2,
\end{equation*}
which proves \cref{eq:balanced-clipping-bias-gaussian}.
The Gaussian tail moment bound \cref{eq:gaussian-radial-tail-moment}, with $R=\sqrt{d_z}+x$, proves \cref{eq:balanced-clipping-bias}.

\label{thm:balanced-score-oracle}
Fix $N \ge 1$, $R_{\mathrm{lab}} > 0$, $0 \le R_{\mathrm{pred}}<\infty$, and $0\le\varepsilon_{\mathrm{cov}}\le R_{\mathrm{pred}}+R_{\mathrm{lab}}$.
Let ${\mathcal{D}}_N^{\mathrm{dsm}}$ be the i.i.d.\ augmented training sample in \cref{eq:dsm-augmented-iid,eq:dsm-training-sample}, and let ${\mathcal{S}}$ be a nonempty deterministic class of jointly Borel scores satisfying
\begin{align}
  \sup_{s\in{\mathcal{S}}}\sup_{z,t,h}\|\sigma_t s(z,t,h)\|_2
  &\le R_{\mathrm{pred}},
  \nonumber\\
  N_{\mathrm{cov}}(\varepsilon_{\mathrm{cov}},{\mathcal{S}},
  d_{\mathrm{bal},\infty})&<\infty.
  \label{eq:score-class-envelope}
\end{align}
Let $\widehat{s}_N \in {\mathcal{S}}$ be a jointly measurable approximate ERM satisfying \cref{eq:approximate-erm} with deterministic optimization error $\varepsilon_{\mathrm{opt}}$.
For every $\delta \in (0, 1)$, with probability at least $1-\delta$ over ${\mathcal{D}}_N^{\mathrm{dsm}}$,
\begin{align}
  {\mathcal{E}}_{\mathrm{score}}(\widehat{s}_N)
  &\lesssim
  {\mathcal{E}}_{\mathrm{app}}({\mathcal{S}})
  +\varepsilon_{\mathrm{lab,clip}}^2(R_{\mathrm{lab}})
  +\varepsilon_{\mathrm{opt}}
  \nonumber\\
  &\quad+A_{t_0, T}(R_{\mathrm{pred}}+R_{\mathrm{lab}})\varepsilon_{\mathrm{cov}}
  \nonumber\\
  &\quad+A_{t_0, T}(R_{\mathrm{pred}}+R_{\mathrm{lab}})^2
  \frac{\log\!\bigl(2N_{\mathrm{cov}}(\varepsilon_{\mathrm{cov}},
  {\mathcal{S}},d_{\mathrm{bal},\infty})/\delta\bigr)}{N}.
  \label{eq:balanced-score-oracle}
\end{align}

We first show that the excess loss has variance controlled by its expectation.
This gives a Bernstein bound on a finite score cover, which we extend to the entire score class before applying the approximate-ERM inequality and converting the clipped regression error to score error.

The clipped regression function satisfies
\begin{equation*}
  \widetilde{s}_{R_{\mathrm{lab}}}^{\mathrm{lab}}(Z_{\tau}, \tau, H_n)
  = {\mathbb{E}}[\xi_{R_{\mathrm{lab}}}^{\mathrm{clip}}\,|\, Z_{\tau}, \tau, H_n],
  \qquad
  \|\widetilde{s}_{R_{\mathrm{lab}}}^{\mathrm{lab}}(Z_{\tau}, \tau, H_n)\|_2
  \le R_{\mathrm{lab}}
\end{equation*}
almost surely.
For $s \in {\mathcal{S}}$, define its clipped excess loss by
\begin{align*}
  L_s^{\mathrm{exc}}
  &:= \|\widetilde{s}(Z_{\tau}, \tau, H_n)-\xi_{R_{\mathrm{lab}}}^{\mathrm{clip}}\|_2^2
  -\|\widetilde{s}_{R_{\mathrm{lab}}}^{\mathrm{lab}}(Z_{\tau}, \tau, H_n)-\xi_{R_{\mathrm{lab}}}^{\mathrm{clip}}\|_2^2,
  \\
  {\mathbb{E}}[L_s^{\mathrm{exc}}]
  &= {\mathbb{E}}\|\widetilde{s}(Z_{\tau}, \tau, H_n)
  -\widetilde{s}_{R_{\mathrm{lab}}}^{\mathrm{lab}}(Z_{\tau}, \tau, H_n)\|_2^2.
\end{align*}
The second identity is the regression Pythagorean identity, and all expectations below are over one episode augmented for variance-balanced DSM.
For brevity, put
\begin{equation*}
  R_{\mathrm{loss}} := R_{\mathrm{pred}}+R_{\mathrm{lab}},
  \qquad
  \Gamma_{\mathrm{cov}}(\delta)
  := \log\!\bigl(2N_{\mathrm{cov}}(\varepsilon_{\mathrm{cov}},{\mathcal{S}},d_{\mathrm{bal},\infty})
  /\delta\bigr).
\end{equation*}
The difference of squared losses factors as
\begin{equation*}
  L_s^{\mathrm{exc}}
  = \left\langle
  \widetilde{s}(Z_{\tau}, \tau, H_n)
  -\widetilde{s}_{R_{\mathrm{lab}}}^{\mathrm{lab}}(Z_{\tau}, \tau, H_n),
  \widetilde{s}(Z_{\tau}, \tau, H_n)
  +\widetilde{s}_{R_{\mathrm{lab}}}^{\mathrm{lab}}(Z_{\tau}, \tau, H_n)
  -2\xi_{R_{\mathrm{lab}}}^{\mathrm{clip}}
  \right\rangle.
\end{equation*}
The first factor is the prediction error relative to the clipped regression function; the bounds on the scaled scores and clipped labels control the second factor.
Together with the regression identity above, this gives
\begin{equation*}
  |L_s^{\mathrm{exc}}| \le 3R_{\mathrm{loss}}^2,
  \qquad
  {\mathbb{E}}[(L_s^{\mathrm{exc}})^2]
  \le 9R_{\mathrm{loss}}^2{\mathbb{E}}[L_s^{\mathrm{exc}}].
\end{equation*}
In particular, $|L_s^{\mathrm{exc}}-{\mathbb{E}}[L_s^{\mathrm{exc}}]| \le 6R_{\mathrm{loss}}^2$ and $\mathrm{Var}(L_s^{\mathrm{exc}}) \le 9R_{\mathrm{loss}}^2{\mathbb{E}}[L_s^{\mathrm{exc}}]$.
Thus the excess losses obey the variance--expectation condition underlying standard fast-rate regression bounds \citep{bartlettbousquetmendelson2005,koltchinskii2011oracle}.
Here a finite-cover argument suffices; we do not invoke a theorem based on local Rademacher complexity for the nonconvex Transformer class.
Under the convention in \cref{app:sec:transformer-approximation} that cover centers belong to the score class, let ${\mathcal{S}}_{\mathrm{cov}}(\varepsilon_{\mathrm{cov}})\subseteq{\mathcal{S}}$ be a minimum-cardinality $\varepsilon_{\mathrm{cov}}$-net in $d_{\mathrm{bal},\infty}$.
This net is used only in the proof; empirical minimization remains over the entire score class ${\mathcal{S}}$.
Let $\widehat{{\mathbb{E}}}_N$ denote the empirical average over the $N$ episodes augmented for variance-balanced DSM.
Bernstein's inequality \citep{boucheron2013concentration} and a union bound imply that, with probability at least $1-\delta$, simultaneously for every $u \in {\mathcal{S}}_{\mathrm{cov}}(\varepsilon_{\mathrm{cov}})$,
\begin{equation}
  |\widehat{{\mathbb{E}}}_N[L_u^{\mathrm{exc}}]-{\mathbb{E}}[L_u^{\mathrm{exc}}]|
  \le
  \sqrt{\frac{18R_{\mathrm{loss}}^2{\mathbb{E}}[L_u^{\mathrm{exc}}]\Gamma_{\mathrm{cov}}(\delta)}{N}}
  +\frac{4R_{\mathrm{loss}}^2\Gamma_{\mathrm{cov}}(\delta)}{N}.
  \label{eq:appendix-bernstein-two-sided}
\end{equation}
For every $s \in {\mathcal{S}}$, choose $s^{\sharp} \in {\mathcal{S}}_{\mathrm{cov}}(\varepsilon_{\mathrm{cov}})$ satisfying
\begin{equation*}
  \|\sigma_t s-\sigma_t s^{\sharp}\|_{\infty,2}
  \le \varepsilon_{\mathrm{cov}}.
\end{equation*}
The difference of squares and the bounds on the scaled score maps and clipped labels give
\begin{equation}
  |L_s^{\mathrm{exc}}-L_{s^{\sharp}}^{\mathrm{exc}}|
  \le 2R_{\mathrm{loss}}\varepsilon_{\mathrm{cov}},
  \qquad
  {\mathbb{E}}[L_{s^{\sharp}}^{\mathrm{exc}}]
  \le 2{\mathbb{E}}[L_s^{\mathrm{exc}}]+2\varepsilon_{\mathrm{cov}}^2.
  \label{eq:appendix-cover-transfer}
\end{equation}
The first inequality controls both its empirical and population averages.
Combining \cref{eq:appendix-bernstein-two-sided,eq:appendix-cover-transfer}, using $\varepsilon_{\mathrm{cov}} \le R_{\mathrm{loss}}$, and applying $ab \le (a^2+b^2)/2$ to the resulting cross term yields, on the same event,
\begin{equation}
  |\widehat{{\mathbb{E}}}_N[L_s^{\mathrm{exc}}]-{\mathbb{E}}[L_s^{\mathrm{exc}}]|
  \lesssim
  \sqrt{\frac{R_{\mathrm{loss}}^2{\mathbb{E}}[L_s^{\mathrm{exc}}]\Gamma_{\mathrm{cov}}(\delta)}{N}}
  +\frac{R_{\mathrm{loss}}^2\Gamma_{\mathrm{cov}}(\delta)}{N}
  +R_{\mathrm{loss}}\varepsilon_{\mathrm{cov}},
  \qquad s \in {\mathcal{S}}.
  \label{eq:appendix-full-class-bernstein}
\end{equation}

For any deterministic $s\in{\mathcal{S}}$, subtract the empirical loss of the clipped regression function from \cref{eq:approximate-erm}.
Apply \cref{eq:appendix-full-class-bernstein} to both $\widehat{s}_N$ and $s$ on its simultaneous event.
Young's inequality absorbs the square-root term involving ${\mathbb{E}}[L_{\widehat{s}_N}^{\mathrm{exc}}]$ into the left side and bounds the comparator's square-root term by its risk plus the complexity term.
Multiplying by $A_{t_0,T}$ yields
\begin{equation*}
  A_{t_0, T}{\mathbb{E}}[L_{\widehat{s}_N}^{\mathrm{exc}}]
  \lesssim
  A_{t_0, T}{\mathbb{E}}[L_s^{\mathrm{exc}}]
  +A_{t_0, T}R_{\mathrm{loss}}^2\frac{\Gamma_{\mathrm{cov}}(\delta)}{N}
  +A_{t_0, T}R_{\mathrm{loss}}\varepsilon_{\mathrm{cov}}
  +\varepsilon_{\mathrm{opt}}.
\end{equation*}
For every $s \in {\mathcal{S}}$, the squared triangle inequality and the inverse-variance time distribution give
\begin{equation*}
  A_{t_0, T}{\mathbb{E}}[L_s^{\mathrm{exc}}]
  \le 2{\mathcal{E}}_{\mathrm{score}}(s)
  +2\varepsilon_{\mathrm{lab,clip}}^2(R_{\mathrm{lab}}),
\end{equation*}
while \cref{eq:clipped-to-exact-score} gives
\begin{equation*}
  {\mathcal{E}}_{\mathrm{score}}(\widehat{s}_N)
  \le 2A_{t_0, T}{\mathbb{E}}[L_{\widehat{s}_N}^{\mathrm{exc}}]
  +2\varepsilon_{\mathrm{lab,clip}}^2(R_{\mathrm{lab}}).
\end{equation*}
By the convention of \cref{app:subsec:episodic-learning}, for each realized training sample this population error is exactly the conditional error on a fresh episode.
Combining the preceding bounds and taking the infimum over $s \in {\mathcal{S}}$ proves \cref{eq:balanced-score-oracle} with a universal implicit constant.
Every concentration variable above is one complete episode augmented for variance-balanced DSM; auxiliary perturbations of the same episode do not increase the independent sample size beyond $N$.

\label{lem:cube-holder-tv-stopping}
Let $P({\mathrm{d}} z) = p(z) \,{\mathrm{d}} z$ on ${\mathcal{Z}} = [0, 1]^{d_z}$ with $p \in {\mathcal{F}}_{\beta}^{d_z}(L_{\beta})$, and let $P_t$ be its OU evolution in \cref{eq:forward-ou-fixed-time}.
There is $C_{\mathrm{stop}} = C_{\mathrm{stop}}(\beta, d_z, L_{\beta}) < \infty$ such that, for every $0 < t \le 1$,
\begin{align*}
  {\mathsf{TV}}\left((\mathrm{Proj}_{{\mathcal{Z}}})_{\#}P_t, P\right)
  &\le {\mathsf{TV}}(P_t, P)
  \le C_{\mathrm{stop}}t^{\beta'/2}.
\end{align*}
No lower density bound is required.

Write $d=d_z$, and let $\bar{p}$ be the zero extension of $p$ from ${\mathcal{Z}}=[0,1]^d$ to ${\mathbb{R}}^d$.
First note the global translation modulus
\begin{equation}
  \|\bar{p}(\cdot-y)-\bar{p}\|_{L^1({\mathbb{R}}^d)}
  \le H_{\mathrm{tr}}\|y\|_2^{\beta'},
  \qquad y \in {\mathbb{R}}^d,
  \label{eq:appendix-zero-extension-translation}
\end{equation}
for a constant $H_{\mathrm{tr}}=H_{\mathrm{tr}}(d,\beta,L_{\beta})$.
Indeed, on ${\mathcal{Z}}\cap({\mathcal{Z}}+y)$ the H\"older condition gives a bound of order $\|y\|_2^{\beta'}$ (the bounded gradient gives power one when $\beta>1$), while the two boundary layers have Lebesgue measure at most $C_d\min\{1,\|y\|_2\}$.
Since $\|p\|_{\infty}\le L_{\beta}$, their contribution has the same power for $\|y\|_2\le1$; for larger translations the trivial $L^1$ bound by two proves \cref{eq:appendix-zero-extension-translation} after increasing $H_{\mathrm{tr}}$.

For $0 < \alpha \le 1$, set $D_{\alpha}\bar{p}(x) := \alpha^{-d}\bar{p}(x/\alpha)$.
Uniformly for $e^{-1} \le \alpha \le 1$,
\begin{equation}
  \|D_{\alpha}\bar{p}-\bar{p}\|_1
  \le H_{\mathrm{dil}}(1-\alpha)^{\beta'},
  \label{eq:appendix-zero-extension-dilation}
\end{equation}
for a constant $H_{\mathrm{dil}}=H_{\mathrm{dil}}(d,\beta,L_{\beta})$.
To see this, split the integral over $\alpha{\mathcal{Z}}$ and ${\mathcal{Z}}\setminus\alpha{\mathcal{Z}}$.
The normalization difference and the boundary layer are ${\mathcal{O}}(1-\alpha)$.
On $\alpha{\mathcal{Z}}$ compare $p(x/\alpha)$ with $p(x)$; their arguments are at distance at most $\sqrt{d}(\alpha^{-1}-1)$, so H\"older continuity (or the bounded gradient) gives ${\mathcal{O}}((1-\alpha)^{\beta'})$.
This proves \cref{eq:appendix-zero-extension-dilation}.
A change of variables in \cref{eq:appendix-zero-extension-translation} also gives
\begin{equation}
  \|D_{\alpha}\bar{p}(\cdot-y)-D_{\alpha}\bar{p}\|_1
  \le H_{\mathrm{tr}}\alpha^{-\beta'}\|y\|_2^{\beta'}.
  \label{eq:appendix-dilated-translation}
\end{equation}

Put $\alpha = \alpha_t = e^{-t}$ and $\sigma = \sigma_t$.
Let $\varphi_{\sigma}^{(d)}$ be the centered $d$-variate Gaussian density with covariance $\sigma^2 I_d$.
The OU density is $p_t = \varphi_{\sigma}^{(d)}*D_{\alpha}\bar{p}$.
Minkowski's inequality, \cref{eq:appendix-zero-extension-dilation,eq:appendix-dilated-translation}, and $\xi \sim {\mathcal{N}}(0, I_d)$ yield
\begin{align}
  \|p_t-\bar{p}\|_1
  &\le
  H_{\mathrm{tr}}\alpha^{-\beta'}\sigma^{\beta'}{\mathbb{E}}[\|\xi\|_2^{\beta'}]
  +H_{\mathrm{dil}}(1-\alpha)^{\beta'}.
  \label{eq:appendix-ou-holder-l1}
\end{align}
For $0 < t \le 1$, $\alpha^{-\beta'} \le e$, $\sigma \le \sqrt{2t}$, $1-\alpha \le t$, and ${\mathbb{E}}[\|\xi\|_2^{\beta'}] \le d^{\beta'/2}$.
Dividing \cref{eq:appendix-ou-holder-l1} by two gives ${\mathsf{TV}}(P_t, P) \le C_{\mathrm{stop}}t^{\beta'/2}$.
Finally, projection is a Markov kernel and fixes every point of ${\mathcal{Z}}$, so
\begin{equation*}
  {\mathsf{TV}}((\mathrm{Proj}_{{\mathcal{Z}}})_{\#}P_t, P)
  = {\mathsf{TV}}((\mathrm{Proj}_{{\mathcal{Z}}})_{\#}P_t, (\mathrm{Proj}_{{\mathcal{Z}}})_{\#}P)
  \le {\mathsf{TV}}(P_t, P).
\end{equation*}

\label{cor:conditional-tv-stopping}
Fix $\beta>0$ and $L_\beta\ge1$, and consider either the sample-only or the input--output prompt model in \cref{eq:hierarchical-sample,eq:input-output-episode} with any Borel task prior $\Pi$.
Suppose the task laws admit jointly Borel densities $p_\theta(z)$ in the sample-only model or $f_\theta(x,z)$ in the input--output model, with $p_\Theta\in{\mathcal{F}}_\beta^{d_z}(L_\beta)$ or $f_\Theta\in{\mathcal{F}}_\beta^{d_x+d_z}(L_\beta)$, respectively, $\Pi$-almost surely.
Writing $\beta'=\beta\wedge1$, there is a constant $C_{\mathrm{stop}}$ depending only on $(\beta,L_\beta)$ and the dimensions such that
\begin{equation}
  {\mathbb{E}}\left[{\mathsf{TV}}\left(
  (\mathrm{Proj}_{{\mathcal{Z}}})_{\#}P_{t \,|\, H_n}, P_{0 \,|\, H_n}
  \right)\right]
  \le C_{\mathrm{stop}}t^{\beta'/2},
  \qquad 0 < t \le 1.
  \label{eq:posterior-predictive-tv-stopping}
\end{equation}
For any standard Borel space $\mathcal{U}$ and Borel map $\phi_{\mathrm{pr}}:{\mathcal{H}}_n\to\mathcal{U}$, set $U=\phi_{\mathrm{pr}}(H_n)$.
Write $P_{0\mid U}:=\mathsf{Law}(Z_0\mid U)$ and $P_{t\mid U}:=\mathsf{Law}(Z_t\mid U)$.
The same bound holds with $H_n$ replaced by $U$.
In the input--output model, the expectation is over the query drawn from its input marginal; no lower bound on its marginal density is assumed.

\label{lem:finite-energy-girsanov}
Fix $d\in\mathbb{N}$, a finite path horizon $T_{\mathrm{path}}>0$, and an initial distribution $\mu\in{\mathcal{P}}({\mathbb{R}}^d)$.
Let $\mathsf{Q}$ be the law on $C([0,T_{\mathrm{path}}];{\mathbb{R}}^d)$ of
\begin{equation*}
  {\mathrm{d}} Y_r = b(r, Y_r) \,{\mathrm{d}} r+\sqrt{2}\,{\mathrm{d}} W_r,
  \qquad Y_0 \sim \mu,
\end{equation*}
where $b:[0,T_{\mathrm{path}}]\times{\mathbb{R}}^d\to{\mathbb{R}}^d$ is Borel, globally Lipschitz in its state variable uniformly in $r$, and has linear growth.
Let $b^{\star}:[0,T_{\mathrm{path}}]\times{\mathbb{R}}^d\to{\mathbb{R}}^d$ be Borel, and let $\mathsf{P}^{\star}$ be the law of a weak solution with the same initial distribution and drift $b^{\star}$.
If
\begin{equation*}
  {\mathbb{E}}_{\mathsf{P}^{\star}}\int_0^{T_{\mathrm{path}}}
  \|b^{\star}(r, Y_r)-b(r, Y_r)\|_2^2 \,{\mathrm{d}} r < \infty,
\end{equation*}
then
\begin{equation}
  \mathrm{KL}(\mathsf{P}^{\star}\|\mathsf{Q})
  \le \frac{1}{4}{\mathbb{E}}_{\mathsf{P}^{\star}}\int_0^{T_{\mathrm{path}}}
  \|b^{\star}(r, Y_r)-b(r, Y_r)\|_2^2 \,{\mathrm{d}} r.
  \label{eq:finite-energy-girsanov}
\end{equation}
The same conclusion holds when the reference process is defined by a recursively frozen nonanticipative drift.
Specifically, choose a deterministic partition $0=r_0<\cdots<r_K=T_{\mathrm{path}}$ and finite-valued Borel maps $a_k:{\mathbb{R}}^d\to{\mathbb{R}}^d$, $0\le k<K$, and set
\begin{equation*}
  b_{\mathrm{fr}}(r,\omega)
  :=\omega_r+2a_k(\omega_{r_k}),
  \qquad r\in[r_k,r_{k+1}),
\end{equation*}
with the last interval closed at $T_{\mathrm{path}}$.
In this alternative case, let $\mathsf{Q}$ denote the law of the unique interval-by-interval solution of ${\mathrm{d}} Y_r=b_{\mathrm{fr}}(r,Y_{[0,r]})\,{\mathrm{d}} r+\sqrt{2}\,{\mathrm{d}} W_r$ with $Y_0\sim\mu$.
In this case, replace $b(r,Y_r)$ in the energy condition and in \cref{eq:finite-energy-girsanov} by $b_{\mathrm{fr}}(r,Y_{[0,r]})$.
The construction includes $a_k(x)=\widehat{s}(x,\vartheta_k,h)$ for fixed score-evaluation times $\vartheta_k$ whenever $\widehat{s}$ is Borel and finite-valued.
The reference process and every post-stopping continuation are then constructed explicitly, interval by interval, so no state regularity of the maps $a_k$ is required.

Put $\Delta b_r=b^{\star}(r,Y_r)-b(r,Y_r)$ in the Markov case and $\Delta b_r=b^{\star}(r,Y_r)-b_{\mathrm{fr}}(r,Y_{[0,r]})$ in the recursively frozen case, and define
\begin{equation*}
  \upsilon_m := \inf\left\{r:\int_0^r\|\Delta b_u\|_2^2 \,{\mathrm{d}} u \ge m\right\}
  \wedge T_{\mathrm{path}}.
\end{equation*}
On the filtered weak-solution space carrying $\mathsf{P}^{\star}$, the process $\Delta b$ is progressively measurable, so $\upsilon_m$ is a stopping time.
On a realization of the weak solution under $\mathsf{P}^{\star}$, retain its path through $\upsilon_m$ and, after $\upsilon_m$, continue with the reference drift and the same Brownian increments.
Global Lipschitzness of $b$ makes this continuation well defined in the Markov case; the recursively frozen case is constructed successively on the remaining grid intervals.
Indeed, conditional on the left endpoint of an interval $[r_k,r_{k+1}]$, its frozen map value is finite and measurable, and the resulting affine SDE has a unique explicit solution.
Induction over the deterministic partition gives weak uniqueness for the recursively frozen reference process and for every post-stopping continuation.
Denote its law by $\mathsf{P}_m$.
The coupling gives
\begin{equation*}
  {\mathsf{TV}}(\mathsf{P}_m, \mathsf{P}^{\star})
  \le \mathsf{P}^{\star}(\upsilon_m < T_{\mathrm{path}})
  \le \frac{1}{m}{\mathbb{E}}_{\mathsf{P}^{\star}}\int_0^{T_{\mathrm{path}}}\|\Delta b_r\|_2^2 \,{\mathrm{d}} r
  \longrightarrow 0.
\end{equation*}
Relative to $\mathsf{Q}$, the drift change under $\mathsf{P}_m$ is $\operatorname{\mathds{1}}\{r\le\upsilon_m\}\Delta b_r$.
Its accumulated squared norm is at most $m$.
Hence Novikov's criterion holds because
\begin{equation*}
  {\mathbb{E}}_{\mathsf{P}_m}\exp\!\left\{
  \frac{1}{4}\int_0^{\upsilon_m}\|\Delta b_r\|_2^2\,{\mathrm{d}} r
  \right\}
  \le e^{m/4}<\infty.
\end{equation*}
If $W^{(m)}$ denotes the Brownian motion driving the process obtained by joining the two segments, define the stochastic exponential
\begin{equation*}
  D_u^{(m)}
  := \exp\left\{-\frac{1}{\sqrt{2}}\int_0^{u\wedge\upsilon_m}
  \Delta b_r^{\top} \,{\mathrm{d}} W_r^{(m)}
  -\frac{1}{4}\int_0^{u\wedge\upsilon_m}\|\Delta b_r\|_2^2 \,{\mathrm{d}} r\right\},
  \qquad 0\le u\le T_{\mathrm{path}}.
\end{equation*}
This process is therefore a true, uniformly integrable martingale of mean one.
Define $\mathsf{Q}_m$ by ${\mathrm{d}}\mathsf{Q}_m/{\mathrm{d}}\mathsf{P}_m=D_{T_{\mathrm{path}}}^{(m)}$. Girsanov's theorem then identifies its drift.
Under $\mathsf{Q}_m$ the coordinate process has the reference drift $b$ in the Markov case and $b_{\mathrm{fr}}$ in the recursively frozen case.
Weak uniqueness for the globally Lipschitz reference equation identifies $\mathsf{Q}_m = \mathsf{Q}$ in the Markov case; the interval-by-interval construction gives the same identification in the recursively frozen case.
Taking the $\mathsf{P}_m$-expectation of $\log({\mathrm{d}}\mathsf{P}_m/{\mathrm{d}}\mathsf{Q})$ eliminates the stochastic integral and gives
\begin{equation*}
  \mathrm{KL}(\mathsf{P}_m\|\mathsf{Q})
  = \frac{1}{4}{\mathbb{E}}_{\mathsf{P}_m}
  \int_0^{\upsilon_m}\|\Delta b_r\|_2^2 \,{\mathrm{d}} r
  = \frac{1}{4}{\mathbb{E}}_{\mathsf{P}^{\star}}
  \int_0^{\upsilon_m}\|\Delta b_r\|_2^2 \,{\mathrm{d}} r.
\end{equation*}
Lower semicontinuity of relative entropy under $\mathsf{P}_m \to \mathsf{P}^{\star}$ in total variation, followed by monotone convergence, proves \cref{eq:finite-energy-girsanov}.

\label{lem:exact-reverse-score-dynamics}
Fix a prompt $h$ for which $P_{0\,|\, h}$ is supported on $[0,1]^{d_z}$, and let $p_t(\cdot\,|\, h)$ and $s_t^{\star}(\cdot\,|\, h)=\nabla\log p_t(\cdot\,|\, h)$ be its OU marginal density and score.
For $0<a<b<\infty$, let $(Y_r)_{0\le r\le b-a}$ be the exact reverse process
\begin{equation*}
  {\mathrm{d}} Y_r
  =\{Y_r+2s_{b-r}^{\star}(Y_r\,|\, h)\}\,{\mathrm{d}} r
  +\sqrt{2}\,{\mathrm{d}} W_r,
  \qquad
  Y_0\sim P_{b\,|\, h}.
\end{equation*}
Then $Y_r\sim P_{b-r\,|\, h}$, and the forward representation $Z_t=\alpha_tZ_0+\sigma_t\xi$ gives
\begin{equation}
  s_t^{\star}(Z_t \,|\, h)
  = -\sigma_t^{-1}{\mathbb{E}}[\xi \,|\, Z_t, h],
  \qquad
  \nabla s_t^{\star}(Z_t \,|\, h)
  = \sigma_t^{-2}\{\mathrm{Cov}(\xi \,|\, Z_t, h)-I_{d_z}\}.
  \label{eq:appendix-randomized-grid-score-identities}
\end{equation}
Consequently,
\begin{align}
  {\mathbb{E}}\|s_t^{\star}(Z_t \,|\, h)\|_2^2
  &\le \frac{d_z}{\sigma_t^2},
  \nonumber\\
  {\mathbb{E}}\|\nabla s_t^{\star}(Z_t \,|\, h)\|_{\mathrm{F}}^2
  &\le \frac{d_z(d_z+3)}{\sigma_t^4}.
  \label{eq:appendix-randomized-grid-fisher-hessian}
\end{align}
Moreover, $S_r:=s_{b-r}^{\star}(Y_r\,|\, h)$ is a continuous semimartingale satisfying
\begin{equation}
  {\mathrm{d}} S_r
  =-S_r\,{\mathrm{d}} r
  +\sqrt{2}\,\nabla s_{b-r}^{\star}(Y_r\,|\, h)\,{\mathrm{d}} W_r.
  \label{eq:appendix-randomized-grid-score-process}
\end{equation}
All identities hold on the full interval $0\le r\le b-a$ in the usual localized It\^o sense.

\label{prop:randomized-grid-discretization}
Consider the randomized time-grid sampler in \cref{app:subsec:randomized-grid-sampler}.
Let $\widehat{s}$ be trained independently of the test episode.
Conditionally on the completed training run, assume that $\widehat{s}$ is finite-valued and jointly Borel and that ${\mathcal{E}}_{\mathrm{score}}(\widehat{s})<\infty$.
Then
\begin{align}
  &{\mathbb{E}}{\mathsf{TV}}\bigl(
  \widehat{Q}_{t_0 \,|\, H_n}^{\mathrm{grid},h_{\mathrm{grid}}},
  P_{t_0 \,|\, H_n}\bigr)
  \le
  \varepsilon_{\mathrm{init}}(T-h_{\mathrm{grid}})
  +\sqrt{\frac{{\mathcal{E}}_{\mathrm{score}}(\widehat{s})}{2}}
  +\varepsilon_{\mathrm{grid}}(h_{\mathrm{grid}}),
  \label{eq:randomized-grid-discretization-bound}\\
  &\varepsilon_{\mathrm{grid}}(h_{\mathrm{grid}})
  :=
  \left\{
    \frac{d_z(T-t_0)h_{\mathrm{grid}}^2}{6}
    +d_z(d_z+3)e^{2h_{\mathrm{grid}}}h_{\mathrm{grid}} A_{t_0,T}
  \right\}^{1/2},
  \quad h_{\mathrm{grid}}>0.
  \label{eq:randomized-grid-discretization-error}
\end{align}
The number of reverse updates is at most $\lceil A_{t_0,T}/h_{\mathrm{grid}}\rceil$ almost surely.

We first compare the exact reverse process with the process that uses the same initialization and freezes the score on each time-grid cell.
The score difference splits into variation of the exact score within each cell and learned-score error at the grid nodes; averaging over the random shift controls the latter by the integrated score error.
The finite-energy KL bound then gives a TV bound, after which we account for Gaussian initialization.

Condition on the learned score and fix a fresh prompt $h$ in a common full-measure set on which the conditional integrated squared score error is finite.

To bound the variation of the exact score, consider one time-grid cell.
Let $Y_r$ be the exact reverse path initialized at its upper forward time and write $S_r = s_{v_j-r}^{\star}(Y_r \,|\, h)$ for $0 \le r \le \Delta_j = v_j-v_{j-1}$.
Define the integrated squared error from freezing the exact score within each time-grid cell by
\begin{equation*}
  \mathcal{F}_h(U_{\mathrm{grid}})
  :=\sum_{j=0}^{J_{\mathrm{grid}}}
  \int_0^{\Delta_j}{\mathbb{E}}\|S_r-S_0\|_2^2 \,{\mathrm{d}} r.
\end{equation*}
Applying \cref{lem:exact-reverse-score-dynamics} with $(a,b)=(v_{j-1},v_j)$ gives \cref{eq:appendix-randomized-grid-fisher-hessian,eq:appendix-randomized-grid-score-process} on this cell.

The time grid satisfies
\begin{equation*}
  \frac{{\mathrm{d}}}{{\mathrm{d}}\mathsf{A}_{t_0}(t)}\log\sigma_t^2
  = 2e^{-2t} \le 2.
\end{equation*}
Hence, whenever $t \in [v_{j-1}, v_j]$,
\begin{equation}
  \Delta_j \le h_{\mathrm{grid}}\sigma_{v_j}^2
  \le h_{\mathrm{grid}}e^{2h_{\mathrm{grid}}}
  \sigma_t^2,
  \qquad
  \Delta_j \le h_{\mathrm{grid}}.
  \label{eq:appendix-randomized-grid-cell-length}
\end{equation}
Solving \cref{eq:appendix-randomized-grid-score-process} on the cell gives
\begin{equation*}
  S_r-S_0 = (e^{-r}-1)S_0
  +\sqrt{2}\int_0^re^{-(r-u)}
  \nabla s_{v_j-u}^{\star}(Y_u \,|\, h) \,{\mathrm{d}} W_u.
\end{equation*}
The two terms are orthogonal in $L^2$.
Since $\int_0^{\Delta_j}(1-e^{-r})^2 \,{\mathrm{d}} r \le \Delta_j^3/3$, ${\mathbb{E}}\|S_0\|_2^2 \le d_z/\sigma_{v_j}^2$, and $\Delta_j/\sigma_{v_j}^2 \le h_{\mathrm{grid}}$, the summed drift contribution is at most $d_z(T-t_0)h_{\mathrm{grid}}^2/3$.
It\^o isometry bounds the summed martingale contribution by
\begin{equation*}
  2\sum_j\Delta_j\int_{v_{j-1}}^{v_j}
  {\mathbb{E}}\|\nabla s_t^{\star}(Z_t \,|\, h)\|_{\mathrm{F}}^2 \,{\mathrm{d}} t.
\end{equation*}
Use $\Delta_j/\sigma_t^2 \le h_{\mathrm{grid}}e^{2h_{\mathrm{grid}}}$ and \cref{eq:appendix-randomized-grid-fisher-hessian}.
Summing the cells gives
\begin{equation}
  \mathcal{F}_h(U_{\mathrm{grid}})
  \le \frac{d_z}{3}(T-t_0)h_{\mathrm{grid}}^2
  +2d_z(d_z+3)e^{2h_{\mathrm{grid}}}
  h_{\mathrm{grid}}A_{t_0,T}.
  \label{eq:appendix-randomized-grid-freezing-energy}
\end{equation}
This bound is uniform in $h$ and $U_{\mathrm{grid}}$.

We next control the learned-score error at the grid nodes.
Since the learned score is only measurable, we use averaging over the random shift rather than a time-continuity bound.
Put
\begin{equation*}
  e_h(t) := {\mathbb{E}}_{P_{t \,|\, h}}
  \|s_t^{\star}(Z_t \,|\, h)-\widehat{s}(Z_t, t, h)\|_2^2.
\end{equation*}
Joint Borel measurability of the scores and the conditional OU kernel makes $e_h$ Lebesgue measurable, and the finite conditional integrated squared score error makes it integrable.
A random grid shift hits any null set of exceptional times with probability zero; the countable union over lattice indices is still null.
By \cref{eq:appendix-randomized-grid-cell-length}, the learned-score grid contribution is at most
\begin{equation*}
  \mathcal{E}_h^{\mathrm{grid}}(U_{\mathrm{grid}})
  := h_{\mathrm{grid}}
  \sum_{j = 0}^{J_{\mathrm{grid}}}\sigma_{v_j}^2e_h(v_j).
\end{equation*}
Averaging the shifted lattice over $U_{\mathrm{grid}}$ and applying the change of variables $x = \mathsf{A}_{t_0}(t)$ gives exactly
\begin{align}
  {\mathbb{E}}_{U_{\mathrm{grid}}}\mathcal{E}_h^{\mathrm{grid}}(U_{\mathrm{grid}})
  &= \int_0^{A_{t_0,T}}\sigma_{\mathsf{A}_{t_0}^{-1}(x)}^2
  e_h\{\mathsf{A}_{t_0}^{-1}(x)\} \,{\mathrm{d}} x
  = \int_{t_0}^Te_h(t) \,{\mathrm{d}} t.
  \label{eq:appendix-randomized-grid-quadrature}
\end{align}

The two integrated squared-error bounds now control the difference between the exact and frozen reverse drifts.
For almost every grid shift $u$, let $\mathsf{P}_{h,u}^{\star}$ be the exact reverse path law initialized from $P_{\widetilde{T}_{\mathrm{grid}}(u)\,|\, h}$, and let $\mathsf{Q}_{h,u}$ be the equally initialized recursively frozen path law.
Represent both paths in the decreasing forward-time coordinate $t\in[t_0,\widetilde{T}_{\mathrm{grid}}(u)]$, write $Z_t^{\leftarrow}$ for the coordinate process under $\mathsf{P}_{h,u}^{\star}$, and let $\kappa_u(t)=v_j$ for almost every $t\in[v_{j-1},v_j]$.
Define the integrated squared score error along the full reverse path
\begin{equation*}
  \mathcal{I}_h(u)
  :=\int_{t_0}^{\widetilde{T}_{\mathrm{grid}}(u)}
  {\mathbb{E}}_{\mathsf{P}_{h,u}^{\star}}\!\left[
  \left\|s_t^{\star}(Z_t^{\leftarrow}\,|\, h)
  -\widehat{s}(Z_{\kappa_u(t)}^{\leftarrow},\kappa_u(t),h)\right\|_2^2
  \right] \,{\mathrm{d}} t.
\end{equation*}
The reference process is defined interval by interval by the explicit exponential--Euler formula, so finite-valued Borel evaluation of $\widehat{s}$ suffices to construct it with the score frozen on each interval.
The reverse-drift difference is twice the score difference defining $\mathcal{I}_h(u)$, so the factor $1/4$ in \cref{eq:finite-energy-girsanov} gives the first inequality below.
Minkowski's inequality with respect to time and the exact reverse-path law, followed by \cref{eq:appendix-randomized-grid-cell-length}, gives the remaining inequalities:
\begin{align*}
  \mathrm{KL}\!\left(\mathsf{P}_{h,u}^{\star}\|\mathsf{Q}_{h,u}\right)
  &\le \mathcal{I}_h(u),
  \\
  \mathcal{I}_h(u)^{1/2}
  &\le \mathcal{F}_h(u)^{1/2}
  +\left\{\sum_{j=0}^{J_{\mathrm{grid}}}\Delta_j e_h(v_j)\right\}^{1/2}
  \\
  &\le \mathcal{F}_h(u)^{1/2}+\mathcal{E}_h^{\mathrm{grid}}(u)^{1/2}.
\end{align*}
Pinsker's inequality, Jensen's inequality in $U_{\mathrm{grid}}$, \cref{eq:appendix-randomized-grid-freezing-energy}, and \cref{eq:appendix-randomized-grid-quadrature} yield the last two terms in \cref{eq:randomized-grid-discretization-bound} after averaging over $h$.

It remains to replace the exact terminal distribution by the sampler's Gaussian initialization.
Since $A_{t_0,T}-\mathsf{A}_{t_0}(\widetilde{T}_{\mathrm{grid}}) < h_{\mathrm{grid}}$ and ${\mathrm{d}} t/{\mathrm{d}}\mathsf{A} = \sigma_t^2 \le 1$, we have $\widetilde{T}_{\mathrm{grid}} \in [T-h_{\mathrm{grid}}, T]$.
Invariance of ${\mathcal{N}}(0,I_{d_z})$ under the OU semigroup and TV contraction give the terminal term $\varepsilon_{\mathrm{init}}(T-h_{\mathrm{grid}})$.
Convexity of TV in the first argument permits averaging the output distribution over $U_{\mathrm{grid}}$.
The update count follows because, with $x = A_{t_0,T}/h_{\mathrm{grid}}$ and $y = U_{\mathrm{grid}}/h_{\mathrm{grid}} \in (0, 1)$, $J_{\mathrm{grid}}+1 = \lfloor x-y\rfloor+1 \le \lceil x\rceil$ almost surely.

The conditions on $M$ give $A_{t_0,T}/M \le \min\{1/2, A_{t_0,T}, T-t_0\}$, so \cref{prop:randomized-grid-discretization} applies with $h_{\mathrm{grid}}=A_{t_0,T}/M$.
Projection contracts TV, and the triangle inequality adds the conditional stopping error from \cref{cor:conditional-tv-stopping}.
With $h_{\mathrm{grid}}=A_{t_0,T}/M$, subadditivity of the square root in \cref{eq:randomized-grid-discretization-error} gives
\begin{equation*}
  \varepsilon_{\mathrm{grid}}(A_{t_0,T}/M)
  \le
  \frac{A_{t_0,T}}{M}\sqrt{\frac{d_z(T-t_0)}{6}}
  +e^{A_{t_0,T}/M}\frac{A_{t_0,T}}{\sqrt{M}}\sqrt{d_z(d_z+3)}.
\end{equation*}
The update count is $\lceil A_{t_0,T}/(A_{t_0,T}/M)\rceil = M$.
Substitution proves the claim.
Since $\sigma_t^2\le1$, one has $T-t_0\le A_{t_0,T}$, and the condition $M\ge2A_{t_0,T}$ gives $e^{A_{t_0,T}/M}\le e^{1/2}$.
If $M\ge C_{\mathrm{disc}}\varepsilon_{\mathrm{disc}}^{-2}(A_{t_0,T}+1)^2$, the sum of the two discretization terms is at most
\begin{equation*}
  \frac{\sqrt{d_z/6}}{C_{\mathrm{disc}}}
  \frac{A_{t_0,T}^{3/2}}{(A_{t_0,T}+1)^2}\varepsilon_{\mathrm{disc}}^2
  +\frac{e^{1/2}\sqrt{d_z(d_z+3)}}{\sqrt{C_{\mathrm{disc}}}}
  \frac{A_{t_0,T}}{A_{t_0,T}+1}\varepsilon_{\mathrm{disc}}.
\end{equation*}
Choosing $C_{\mathrm{disc}}(d_z)$ sufficiently large makes this expression at most $\varepsilon_{\mathrm{disc}}$ for every $0<\varepsilon_{\mathrm{disc}}\le1$.

\label{lem:smooth-latent-explicit-tail-bounds}
Use the diffusion times and radii in \cref{eq:accuracy-diffusion-times,eq:smooth-latent-explicit-radii}, with $\beta'=\beta\wedge1$.
Let $\delta_{\mathrm{tail},n}$ and $\varepsilon_{\mathrm{tail},n}^2$ be the probability and score-energy terms in \cref{eq:transformer-good-event-probability,eq:transformer-exceptional-score-energy}.
There is $\varepsilon_1\in(0,1]$, depending only on $d_z$, $\beta'$, $C_{\mathrm{stop}}$, $c_{\mathrm{state}}$, and $c_{\mathrm{lab}}$, such that, for $0<\varepsilon\le\varepsilon_1$ and $c_{\mathrm{state}}\ge2\sqrt{d_z}$, the following bounds hold with implicit constants depending only on the same quantities:
\begin{align}
  \sigma_{t_0}^{-1}
  &\lesssim \varepsilon^{-1/\beta'},
  &
  A
  &\lesssim \log(e/\varepsilon),
  \label{eq:smooth-latent-tail-time-prefactors}\\
  R_{\mathrm{bal},n}^2
  &\lesssim \log(e/\varepsilon)\varepsilon^{-2/\beta'},
  &
  \delta_{\mathrm{tail},n}
  &\le \varepsilon^{c_{\mathrm{state}}^2/8},
  \label{eq:smooth-latent-tail-radius-probability}\\
  \varepsilon_{\mathrm{tail},n}^2
  &\lesssim \log(e/\varepsilon)
  \varepsilon^{c_{\mathrm{state}}^2/16-2/\beta'},
  \label{eq:smooth-latent-tail-energy-rate}\\
  AR_{\mathrm{bal},n}^2
  \delta_{\mathrm{tail},n}
  &\lesssim \log^2(e/\varepsilon)
  \varepsilon^{c_{\mathrm{state}}^2/8-2/\beta'},
  \label{eq:smooth-latent-tail-envelope-rate}\\
  \varepsilon_{\mathrm{lab,clip}}^2
  \{R_{\mathrm{lab},n}\}
  &\lesssim \log(e/\varepsilon)\varepsilon^{c_{\mathrm{lab}}^2/2}.
  \label{eq:smooth-latent-label-tail-rate}
\end{align}
Consequently, if
\begin{equation}
  \frac{c_{\mathrm{state}}^2}{16}
  >2+\frac{2}{\beta'},
  \qquad
  \frac{c_{\mathrm{lab}}^2}{2}>2,
  \label{eq:smooth-latent-tail-constant-condition}
\end{equation}
then
\begin{equation}
  4AR_{\mathrm{bal},n}^2
  \delta_{\mathrm{tail},n}
  +4\varepsilon_{\mathrm{tail},n}^2
  +\varepsilon_{\mathrm{lab,clip}}^2
  \{R_{\mathrm{lab},n}\}
  =o(\varepsilon^2).
  \label{eq:smooth-latent-tail-total-rate}
\end{equation}
In particular, the left-hand side is at most $c_1\varepsilon^2$ for every fixed $c_1>0$ and all sufficiently small $\varepsilon$.

For $0<t\le1$, concavity of $t\mapsto1-e^{-2t}$ gives
\begin{equation*}
  \sigma_t^2=1-e^{-2t}\ge(1-e^{-2})t.
\end{equation*}
After decreasing $\varepsilon_1$ so that $t_0\le1$, this proves the first bound in \cref{eq:smooth-latent-tail-time-prefactors}.
Moreover, $e^{2t_0}-1\ge2t_0$ and $e^{2T}-1\le e^{2T}$ imply
\begin{equation*}
  A
  \le T+\frac{1}{2}\log\{1/(2t_0)\}
  \lesssim \log(e/\varepsilon).
\end{equation*}
The definition of $R_{\mathrm{bal},n}$ now gives its bound in \cref{eq:smooth-latent-tail-radius-probability}.

Let $X:=\|\xi\|_2$ for $\xi\sim{\mathcal{N}}(0,I_{d_z})$ and put $a:=c_{\mathrm{state}}\sqrt{\log(e/\varepsilon)}$.
The Gaussian norm concentration inequality gives
\begin{equation*}
  \Pr(X>a)
  \le\exp\{-\tfrac{1}{2}(a-\sqrt{d_z})^2\}
  \le e^{-a^2/8}
  \le\varepsilon^{c_{\mathrm{state}}^2/8},
\end{equation*}
where the second inequality uses $a\ge2\sqrt{d_z}$.
This and \cref{eq:transformer-good-event-probability} prove the probability bound.
Cauchy--Schwarz and the finite fourth Gaussian moment give
\begin{equation*}
  {\mathbb{E}}\!\left[
  (X+2\sqrt{d_z})^2\operatorname{\mathds{1}}\{X>a\}
  \right]
  \le
  \left\{{\mathbb{E}}(X+2\sqrt{d_z})^4\right\}^{1/2}
  \Pr(X>a)^{1/2}
  \lesssim\varepsilon^{c_{\mathrm{state}}^2/16}.
\end{equation*}
Substitution into \cref{eq:derived-score-tail-bound}, together with \cref{eq:smooth-latent-tail-time-prefactors}, proves \cref{eq:smooth-latent-tail-energy-rate}.
Multiplying the bounds for $A$, $R_{\mathrm{bal},n}^2$, and $\delta_{\mathrm{tail},n}$ proves \cref{eq:smooth-latent-tail-envelope-rate}.
Finally, apply \cref{eq:balanced-clipping-bias} with $x=c_{\mathrm{lab}}\sqrt{\log(e/\varepsilon)}$ to obtain \cref{eq:smooth-latent-label-tail-rate}.
Under \cref{eq:smooth-latent-tail-constant-condition}, each exponent remaining after division by $\varepsilon^2$ is strictly positive.
Since $\varepsilon^a\{1+\log(\varepsilon^{-1})\}^k\to0$ for every $a>0$ and fixed $k$, \cref{eq:smooth-latent-tail-total-rate} follows.

\label{thm:main-generation-error-formal}
Under \cref{assump:smooth-latent-task}, for each $n\ge2$ and sufficiently small $\varepsilon>0$, there exists a common DiT score class ${\mathcal{S}}_{n,\varepsilon}^{\mathrm{lat}}$ and diffusion parameters that depend on $(n,\varepsilon)$ and the fixed dimensions and regularity bounds. 
Its number of trainable parameters $\mathsf{N}_{\mathrm{param},n,\varepsilon}^{\mathrm{lat}}$, stored nonzero coefficients, and arithmetic operations per forward pass are polynomial in $(n,\varepsilon^{-1})$. Use the estimator and reverse sampler of Section~\ref{subsec:main-training-and-sampling}, with $N\ge1$ independent pretraining episodes, empirical optimization gap $\varepsilon_{\mathrm{opt}}\lesssim\varepsilon^2$, and an integer $M$ satisfying \cref{eq:admissible-sampling-updates}. 
For every fixed $\mathcal{M}\in\mathfrak{M}_{\mathrm{lat}}$ and $\delta\in(0,1)$, with probability at least $1-\delta$ over the training episodes and their diffusion augmentations,
\begin{equation}
  {\mathbb{E}}{\mathsf{TV}}\!\bigl(\widehat P^{(M)}_{0\mid H_n},P(\cdot\mid H_n)\bigr) \lesssim \varepsilon +\log(e/\varepsilon)\sqrt{\frac{\mathsf{N}_{\mathrm{param},n,\varepsilon}^{\mathrm{lat}}\log(en/\varepsilon)+\log(2/\delta)}{N}} +\frac{\log(e/\varepsilon)}{\sqrt M}.
\end{equation}
The expectation averages a fresh prompt conditional on the completed training run.

\label{thm:main-task-uncertainty-and-minimax-rate}
\emph{Uniform upper bound.}
For every $\mathcal{M}\in\mathfrak{M}_{\mathrm{lat}}$ and $n\ge1$, the following bound holds with an implicit constant depending only on the common class parameters:
\begin{equation}
 {\mathbb{E}}_{\mathcal{M}}\mathrm{KL}\!\bigl(
 P(\cdot\mid H_n,\Theta)\,\|\,P(\cdot\mid H_n)\bigr)
 \lesssim\frac{\log(en)}{n}.
 \label{eq:main-predictive-information-bound}
\end{equation}
Consequently,
\begin{equation*}
 {\mathbb{E}}_{\mathcal{M}}{\mathsf{TV}}\!\bigl(P(\cdot\mid H_n),P(\cdot\mid H_n,\Theta)\bigr)
 \lesssim \sqrt{\frac{\log(en)}{n}}
\end{equation*}
uniformly over $\mathcal{M}\in\mathfrak{M}_{\mathrm{lat}}$.

\emph{Matching lower bound.}
If $H_\theta>0$, $\underline{p}<1$, and $L_\beta>1$, then, for all sufficiently large $n$,
\begin{equation}
 \begin{aligned}
 \sqrt{\frac{\log(en)}{n}}&\lesssim\sup_{\mathcal{M}\in\mathfrak{M}_{\mathrm{lat}}}\mathcal{R}_n^{\mathrm{or}}(\mathcal{M})\\
 &\le\sup_{\mathcal{M}\in\mathfrak{M}_{\mathrm{lat}}}
 {\mathbb{E}}_{\mathcal{M}}{\mathsf{TV}}\!\bigl(P(\cdot\mid H_n),P(\cdot\mid H_n,\Theta)\bigr)
 \lesssim \sqrt{\frac{\log(en)}{n}}.
 \end{aligned}
 \label{eq:main-task-uncertainty-bound}
\end{equation}
The lower bound allows any number of independent training episodes, including a countably infinite sequence, and unrestricted computation at generation time.
The implicit constants and the sufficiently-large-$n$ threshold depend only on the common class parameters.
The worst-case model and prior may depend on $n$, while all class parameters remain fixed.

\label{lem:posterior-averaging}
Suppose the posterior-mixture identity in \cref{eq:main-posterior-predictive-mixture} holds, and let $h \mapsto Q(\cdot \,|\, h)$ be any measurable probability kernel from ${\mathcal{H}}_n$ to ${\mathcal{Z}}$.
Then
\begin{equation*}
  {\mathbb{E}}\left[{\mathsf{TV}}\!\left(P(\cdot \,|\, H_n), P(\cdot \,|\, H_n, \Theta)\right)\right]
  \le
  2{\mathbb{E}}\left[{\mathsf{TV}}\!\left(Q(\cdot\mid H_n), P(\cdot \,|\, H_n, \Theta)\right)\right].
\end{equation*}

Write $Q_h=Q(\cdot\mid h)$ and $R_{h,\theta}=P(\cdot\mid h,\theta)$.
On the common full-measure set where the posterior-mixture identity holds, convexity of TV gives
\begin{equation*}
 {\mathsf{TV}}(Q_h,P(\cdot\mid h))
 \le\int{\mathsf{TV}}(Q_h,R_{h,\theta})\Pi({\mathrm{d}}\theta\mid h).
\end{equation*}
These TV distances are measurable and bounded by one: on a standard Borel space, the defining supremum can be taken over a countable generating algebra.
Taking expectations and applying the tower property yields
\begin{equation*}
 {\mathbb{E}}{\mathsf{TV}}(Q(\cdot\mid H_n),P(\cdot\mid H_n))
 \le{\mathbb{E}}{\mathsf{TV}}(Q(\cdot\mid H_n),P(\cdot\mid H_n,\Theta)).
\end{equation*}
The triangle inequality through $Q(\cdot\mid H_n)$ proves the claim.

\label{lem:latent-predictive-information}
Fix $d_\theta\in\mathbb{N}$ and a probability kernel $\theta\mapsto G_\theta$ on a standard Borel observation space.
Let $\Theta$ have any Borel prior $\Pi$ on $[0,1]^{d_\theta}$, and, conditionally on $\Theta=\theta$, let $U_1,U_2,\ldots$ be i.i.d. with law $G_\theta$.
Suppose that, for some $K_{\mathrm{KL}}\in[0,\infty)$ and $\beta_\theta\in(0,1]$,
\begin{equation}
 \mathrm{KL}(G_\theta\|G_{\theta'})
 \le K_{\mathrm{KL}}\|\theta-\theta'\|_2^{2\beta_\theta}
 \quad\text{for all }\theta,\theta'.
 \label{eq:latent-kl-modulus}
\end{equation}
There is a constant $C_0$, depending only on $(d_\theta,\beta_\theta,K_{\mathrm{KL}})$, such that for every integer $m\ge1$,
\begin{equation}
 I(\Theta;U_{1:m})
 \le C_0+\frac{d_\theta}{2\beta_\theta}\log m.
 \label{eq:latent-cumulative-information}
\end{equation}
Moreover, for every $n\ge0$,
\begin{equation}
 {\mathbb{E}}\mathrm{KL}\!\bigl(
 G_\Theta\,\|\,\mathsf{Law}(U_{n+1}\mid U_{1:n})\bigr)
 \le
 \frac{C_0+\frac{d_\theta}{2\beta_\theta}\log(n+1)}{n+1}.
 \label{eq:latent-one-step-kl}
\end{equation}

Fix $\varepsilon\in(0,1]$.
The latent cube admits a Euclidean $\varepsilon$-net $\{\theta_1,\ldots,\theta_{J_\varepsilon}\}$ with $J_\varepsilon\le C_{d_\theta}\varepsilon^{-d_\theta}$.
For example, subdivide each coordinate into intervals of length at most $\varepsilon/\sqrt{d_\theta}$ and use their centers.
Define the reference law
\begin{equation*}
 Q_{m,\varepsilon}:=
 J_\varepsilon^{-1}\sum_{j=1}^{J_\varepsilon}G_{\theta_j}^{\otimes m}.
\end{equation*}
For each $\theta$, choose a nearest net point.
The mixture dominates $J_\varepsilon^{-1}G_{\theta_j}^{\otimes m}$, so product additivity of KL and \cref{eq:latent-kl-modulus} give
\begin{equation}
 \mathrm{KL}(G_\theta^{\otimes m}\|Q_{m,\varepsilon})
 \le \log J_\varepsilon+mK_{\mathrm{KL}}\varepsilon^{2\beta_\theta}.
 \label{eq:latent-reference-mixture-bound}
\end{equation}
Let $\overline G_m:=\int G_\theta^{\otimes m}\Pi({\mathrm{d}}\theta)$ be the actual marginal law of the examples.
Splitting the log density ratio through $\overline G_m$ and integrating gives
\begin{equation*}
 \int\mathrm{KL}(G_\theta^{\otimes m}\|Q_{m,\varepsilon})
       \Pi({\mathrm{d}}\theta)
 =I(\Theta;U_{1:m})+
   \mathrm{KL}(\overline G_m\|Q_{m,\varepsilon}).
\end{equation*}
The nonnegative final term can be dropped.
Choose $\varepsilon=m^{-1/(2\beta_\theta)}$ in \cref{eq:latent-reference-mixture-bound}.
This proves \cref{eq:latent-cumulative-information} after absorbing $\log C_{d_\theta}+K_{\mathrm{KL}}$ into $C_0$.
The equal weights in $Q_{m,\varepsilon}$ are used only to obtain the bound; the actual prior $\Pi$ has not been replaced or restricted.

Put $\mathcal{I}_k=I(\Theta;U_{k+1}\mid U_{1:k})$.
The chain rule gives
\begin{equation*}
 \sum_{k=0}^{m-1}\mathcal{I}_k=I(\Theta;U_{1:m}).
\end{equation*}
To prove monotonicity, set $F=U_{1:k}$, $A=U_{k+1}$, and $B=U_{k+2}$.
Applying the mutual-information chain rule to $I((\Theta,A);B\mid F)$ in the two possible orders gives
\begin{equation*}
 I(\Theta;B\mid F)+I(A;B\mid\Theta,F)
 = I(A;B\mid F)+I(\Theta;B\mid A,F).
\end{equation*}
Conditional independence makes $I(A;B\mid\Theta,F)=0$.
Conditional exchangeability identifies the first term with $\mathcal{I}_k$ and the final term with $\mathcal{I}_{k+1}$.
Hence
\begin{equation*}
 \mathcal{I}_k-\mathcal{I}_{k+1}=I(U_{k+1};U_{k+2}\mid U_{1:k})\ge0.
\end{equation*}
Therefore
\begin{equation*}
 (n+1)\mathcal{I}_n\le\sum_{k=0}^n\mathcal{I}_k
 =I(\Theta;U_{1:n+1}).
\end{equation*}
Finally, conditional independence gives
\begin{equation*}
 \mathcal{I}_n={\mathbb{E}}\mathrm{KL}\!\bigl(
 G_\Theta\,\|\,\mathsf{Law}(U_{n+1}\mid U_{1:n})\bigr).
\end{equation*}
Combining the last two displays with \cref{eq:latent-cumulative-information} proves \cref{eq:latent-one-step-kl}.
The preceding finite bound also justifies every mutual-information chain-rule identity used here.

Fix $\mathcal{M}\in\mathfrak{M}_{\mathrm{lat}}$.
Let $U_i=Z_i$ in the sample-only model and $U_i=(X_i,Z_i)$ in the input--output model.
Let $G_\theta$ denote its one-example law, with density $g_\theta$ on the unit-volume cube.
Using $\log x\le x-1$ and the normalization of the two densities,
\begin{equation*}
 \mathrm{KL}(G_\theta\|G_{\theta'})
 \le\int\frac{(g_\theta-g_{\theta'})^2}{g_{\theta'}}
 \le\frac{1}{\underline{p}}
        \|g_\theta-g_{\theta'}\|_\infty^2
 \le\frac{H_\theta^2}{\underline{p}}
       \|\theta-\theta'\|_2^{2\beta_\theta}.
\end{equation*}
Thus Lemma~\ref{lem:latent-predictive-information} applies uniformly over all allowed task maps and all Borel priors.

In the sample-only model, the one-step predictive law is $P(\cdot\mid C_n)$, and the oracle is $P_\Theta$.
\Cref{eq:latent-one-step-kl} proves the asserted KL bound.

In the input--output model, put $\mathcal{I}_n=I(\Theta;U_{n+1}\mid U_{1:n})$.
Conditional independence and the KL chain rule give
\begin{align*}
 &{\mathbb{E}}_{\mathcal{M}}\mathrm{KL}\!\bigl(
 P^{Z\mid X}_\Theta(\cdot\mid X_\star)
 \,\|\,P(\cdot\mid C_n,X_\star)\bigr)\\
 &\quad=I(\Theta;Z_\star\mid C_n,X_\star)\\
 &\quad\le I(\Theta;(X_\star,Z_\star)\mid C_n)=\mathcal{I}_n.
\end{align*}
The inequality follows by dropping the nonnegative term $I(\Theta;X_\star\mid C_n)$.
In particular, the argument does not require a task-independent input marginal and still conditions the predictive distribution on the query $X_\star$.
This proves \cref{eq:main-predictive-information-bound} in the second model.

Pinsker's inequality ${\mathsf{TV}}(P,Q)^2\le\mathrm{KL}(P\|Q)/2$ and Jensen's inequality yield
\begin{equation*}
 \begin{aligned}
 &{\mathbb{E}}_{\mathcal{M}}{\mathsf{TV}}\!\bigl(P(\cdot\mid H_n),P(\cdot\mid H_n,\Theta)\bigr)\\
 &\quad\le\sqrt{\frac{1}{2}{\mathbb{E}}_{\mathcal{M}}
 \mathrm{KL}\!\bigl(P(\cdot\mid H_n,\Theta)
       \,\|\,P(\cdot\mid H_n)\bigr)}
 \lesssim \sqrt{\frac{\log(en)}{n}}.
 \end{aligned}
\end{equation*}

\label{cor:task-conditional-prompt-rate}
For all sufficiently large $n$, fix $\mathcal{M}\in\mathfrak{M}_{\mathrm{lat}}$, $N\ge1$, $\delta\in(0,1)$, and an integer $M$ satisfying \cref{eq:admissible-sampling-updates}. Set $\varepsilon=\sqrt{\log(en)/n}$, and use the score class, estimator, and sampler of \cref{thm:main-generation-error} with $\varepsilon_{\mathrm{opt}}\le c_{\mathrm{opt}}\log(en)/n$. With probability at least $1-\delta$ over the training episodes and their diffusion augmentations,
\begin{equation}
 \begin{aligned}
 &{\mathbb{E}}{\mathsf{TV}}\!\bigl(\widehat{P}_{0\,|\,H_n}^{(M)},P(\cdot\mid H_n,\Theta)\bigr)\\
 &\quad\lesssim\sqrt{\frac{\log(en)}{n}}+\log(en)\sqrt{\frac{
 \mathsf{N}_{\mathrm{param},n,\sqrt{\log(en)/n}}^{\mathrm{lat}}\log(en)
 +\log(2/\delta)}{N}}
       +\frac{\log(en)}{\sqrt{M}}.
 \end{aligned}
 \label{eq:main-smooth-latent-generation-rate}
\end{equation}
On the same event, the displayed bound also holds for ${\mathbb{E}}{\mathsf{TV}}\!\bigl(\widehat{P}_{0\,|\,H_n}^{(M)},P(\cdot\mid H_n)\bigr)$. If $N$ and $M$ satisfy \cref{eq:main-predictive-sufficient-choices} with $\varepsilon=\sqrt{\log(en)/n}$, then both TV errors are $\lesssim\sqrt{\log(en)/n}$ and the integrated score error in \cref{eq:main-balanced-score-oracle} is $\lesssim\log(en)/n$. The implicit constants may also depend on $c_{\mathrm{opt}}$. Under the nondegeneracy conditions of \cref{thm:main-task-uncertainty-and-minimax-rate}, take $\delta=n^{-1}$ and these sufficient choices of $N$ and $M$. Then
\begin{equation}
 \begin{aligned}
 \sqrt{\frac{\log(en)}{n}}&\lesssim \mathcal{R}_{n,N}^{\mathrm{lat}}\\
 &\le \sup_{\mathcal{M}\in\mathfrak{M}_{\mathrm{lat}}}
       {\mathbb{E}}_{\mathrm{train},\mathcal{M}}{\mathbb{E}}_{\mathcal{M}}{\mathsf{TV}}\!\bigl(\widehat{P}_{0\,|\,H_n}^{(M)},P(\cdot\mid H_n,\Theta)\bigr)
 \lesssim \sqrt{\frac{\log(en)}{n}}.
 \end{aligned}
 \label{eq:main-latent-minimax-sandwich}
\end{equation}
The lower bound holds for every number of independent training episodes, even if the model is known. The upper bound requires the stated choices of $N$, $M$, and the optimization tolerance.

\label{ex:smooth-latent-peak-shift}
In the sample-only model, let $d_z=d_\theta=1$ and
\begin{equation*}
 g_\theta(z)=1+\tfrac{1}{4}\cos\bigl(2\pi(z-\theta)\bigr),
 \qquad (\theta,z)\in[0,1]^2.
\end{equation*}
The latent coordinate shifts the density's peak without changing its support.
Integration over one period gives normalization, and
\begin{equation*}
 \tfrac{3}{4}\le g_\theta\le\tfrac{5}{4},\qquad
 \|g_\theta\|_{C^1}\le\tfrac{5}{4}+\tfrac{\pi}{2},\qquad
 \sup_z|g_\theta(z)-g_{\theta'}(z)|\le\tfrac{\pi}{2}|\theta-\theta'|,
\end{equation*}
since both $|\partial_zg_\theta|$ and $|\partial_\theta g_\theta|$ are at most $\pi/2$.
Joint continuity and these uniform bounds verify \cref{assump:smooth-latent-task} with $\beta=\beta_\theta=1$, $\underline{p}=3/4$, $L_1=5/4+\pi/2$, and $H_\theta=\pi/2$, for any Borel prior.
The prompt consists of samples from one task; its posterior predictive averages over possible peak locations.

This family also has a simple coefficient-space geometry. Expanding the shifted cosine gives
\begin{equation*}
 g_\theta(z)
 =1+\tfrac14\cos(2\pi\theta)\cos(2\pi z)
   +\tfrac14\sin(2\pi\theta)\sin(2\pi z).
\end{equation*}
Thus, the coefficient vector
$\gamma(\theta)=\tfrac14\bigl(\cos(2\pi\theta),\sin(2\pi\theta)\bigr)$
traces a circle of radius $1/4$. Given $H_n$, the posterior-predictive density is
\begin{equation*}
 \begin{aligned}
 \bar g_n(z)
 &:=\int g_\theta(z)\,\Pi({\mathrm{d}}\theta\mid H_n)
 =1+\bar a_n\cos(2\pi z)+\bar b_n\sin(2\pi z),\\
 (\bar a_n,\bar b_n)
 &:=\int \gamma(\theta)\,\Pi({\mathrm{d}}\theta\mid H_n).
 \end{aligned}
\end{equation*}
Consequently, $\sqrt{\bar a_n^2+\bar b_n^2}\le1/4$, with strict inequality unless the posterior distribution of $\gamma(\Theta)$ is a point mass. The task densities therefore lie on the circle, while their posterior predictive can lie in its interior.

\label{ex:input-output-task-family}
Let $d_x=d_z=1$, let $\psi(x,z)=(2x-1)(2z-1)$, and set
\begin{equation*}
  g_\theta(x,z)=1+\rho(2\theta_1-1)\psi(x,z),
  \qquad \theta\in[0,1]^{d_\theta},\quad (x,z)\in[0,1]^2,
  \quad 0<\rho<1.
\end{equation*}
These are jointly continuous probability densities with $g_\theta\ge1-\rho$ and a common finite spatial $C^\beta$ bound for every fixed $\beta>0$.
Moreover,
\begin{equation*}
  \sup_{x,z}|g_\theta(x,z)-g_{\theta'}(x,z)|
  \le2\rho\|\psi\|_\infty\|\theta-\theta'\|_2.
\end{equation*}
Thus, for sufficiently small $\rho$, this family satisfies \cref{assump:smooth-latent-task} with density floor $1-\rho$ and $\beta_\theta=1$, for any Borel prior.
Because $\int_0^1\psi(x,z)\,{\mathrm{d}} z=0$ for every $x$, the input marginal is uniform, while the conditional output density varies with the task.

\label{ex:smooth-latent-families}
Let $\psi\in C^\infty([0,1]^{d_{\mathrm{stat}}})$ satisfy $\int_{[0,1]^{d_{\mathrm{stat}}}}\psi(u)\,{\mathrm{d}} u=0$ and $\|\psi\|_\infty\le1$, and define
\begin{equation*}
g_\theta(u)=1+\rho(2\theta_1-1)\psi(u), \qquad \theta\in[0,1]^{d_\theta}.
\end{equation*}
For sufficiently small $\rho>0$, this family satisfies \cref{assump:smooth-latent-task} with $\beta_\theta=1$.

\label{ex:smooth-latent-multimodal-mixtures}
Let $\varphi_1,\ldots,\varphi_K$ be fixed smooth densities with separated modes, let $\Delta^{K-1}:=\{w\in[0,1]^K:\sum_{k=1}^K w_k=1\}$, and let $w:[0,1]^{d_\theta}\to\Delta^{K-1}$ be H\"older continuous. Then
\begin{equation*}
g_\theta(u)=(1-\gamma_{\mathrm{mix}})+\gamma_{\mathrm{mix}}\sum_{k=1}^K w_k(\theta)\varphi_k(u)
\end{equation*}
satisfies \cref{assump:smooth-latent-task} for sufficiently small $\gamma_{\mathrm{mix}}>0$. Thus, the relative weights of the modes may vary across tasks.

\label{ex:smooth-latent-exponential-families}
Fix $r\in\mathbb{N}$, let $\phi:[0,1]^{d_{\mathrm{stat}}}\to\mathbb{R}^r$, and let $\eta_{\mathrm{nat}}:[0,1]^{d_\theta}\to\mathbb{R}^r$. The following is a normalized exponential family:
\begin{equation*}
g_\theta(u)=\frac{\exp\{\eta_{\mathrm{nat}}(\theta)^\top\phi(u)\}}{\int_{[0,1]^{d_{\mathrm{stat}}}}\exp\{\eta_{\mathrm{nat}}(\theta)^\top\phi(v)\}\,{\mathrm{d}} v}.
\end{equation*}
It satisfies \cref{assump:smooth-latent-task} when the coordinates of $\phi$ have bounded $C^\beta$ norms, $\eta_{\mathrm{nat}}([0,1]^{d_\theta})$ is compact, and $\eta_{\mathrm{nat}}$ is $\beta_\theta$-H\"older continuous. Hence, the class includes exponential families with bounded parameters, as well as truncated Gaussian families.
